/**
 * The browser-sandbox Worker (nexus-terminal/workers/nexus-browser-sandbox/src/index.ts, bundled unchanged) served on localhost, so the
 * browser MCP's real SandboxPage talks to it exactly as it talks to the hosted one. Safety:
 *   • binds 127.0.0.1 only, on a random port, with a random per-run AUTH_TOKEN (the Worker itself fails closed without it);
 *   • /api/exec (run_command) and /api/interpret* (run_code) execute on THIS machine, so they are refused unless allowExec is set
 *     (NEXUS_BROWSER_ALLOW_EXEC=1) — the user opts in;
 *   • live view (/live) is proxied to websockify on loopback (see shims/cf-sandbox.ts).
 */
import http from 'node:http';
import net from 'node:net';
import crypto from 'node:crypto';
import path from 'node:path';
import sandboxWorker from '@sandbox/worker';
import { verifyLive } from '@worker/live';
import { sandboxConfig, stopLocalSandboxProcesses, claimSandboxInstance } from './shims/cf-sandbox.js';
import { localStore } from './local-store.js';

export interface LocalSandboxServer { url: string; token: string; close(): Promise<void> }

/** A minimal viewer for a signed live link: noVNC (from jsDelivr) connected to this server's /live with the same signed query. */
const VIEWER = (q: string) => `<!doctype html><html><head><meta charset="utf-8"><title>Live browser</title>
<style>html,body{margin:0;height:100%;background:#111;color:#ddd;font:13px system-ui}#bar{padding:6px 10px}#screen{height:calc(100% - 30px)}</style></head>
<body><div id="bar">Live browser — you can watch and take over. <span id="st">connecting…</span></div><div id="screen"></div>
<script type="module">
import RFB from 'https://cdn.jsdelivr.net/npm/@novnc/novnc@1.5.0/core/rfb.js';
const rfb = new RFB(document.getElementById('screen'), 'ws://' + location.host + '/live?${q}');
rfb.scaleViewport = true; rfb.viewOnly = false;
rfb.addEventListener('connect', () => st.textContent = 'connected');
rfb.addEventListener('disconnect', () => st.textContent = 'disconnected');
</script></body></html>`;

/** Signed live links (from the live_view tool) carry their own auth: verify s/exp/sig with the Worker's verifyLive and the run token. */
async function signedLive(url: URL, token: string): Promise<string | null> {
  const s = url.searchParams.get('s') ?? '', exp = Number(url.searchParams.get('exp') ?? 0), sig = url.searchParams.get('sig') ?? '';
  if (!s || !sig || !exp) return null;
  return (await verifyLive(token, s, exp, sig)) ? s : null;
}

const EXEC_PATHS = /^\/api\/(exec|interpret)(\/|$)/;

function freePort(): Promise<number> {
  return new Promise((resolve, reject) => { const s = net.createServer(); s.once('error', reject); s.listen(0, '127.0.0.1', () => { const p = (s.address() as net.AddressInfo).port; s.close(() => resolve(p)); }); });
}

export async function startLocalSandbox(opts: { dir: string; dataDir: string; toolsHome: string; allowExec?: boolean; env?: Record<string, string> }): Promise<LocalSandboxServer> {
  const store = localStore(opts.dataDir);   // the workflow store's SpacetimeDB calls, answered locally (/stdb/…)
  sandboxConfig.dir = opts.dir;
  sandboxConfig.extensionsDir = path.join(opts.toolsHome, 'extensions');
  sandboxConfig.env = { ...(opts.env ?? {}) };
  [sandboxConfig.vncPort, sandboxConfig.wsPort] = [await freePort(), await freePort()];
  claimSandboxInstance();   // own display + ports + profile per process (two sessions / a test during the sync no longer collide)
  [sandboxConfig.relayPort, sandboxConfig.interpPort, sandboxConfig.cdpPort] = [await freePort(), await freePort(), await freePort()];
  await stopLocalSandboxProcesses();   // leftovers from an earlier run would be reused with their old state
  const token = crypto.randomBytes(24).toString('hex');
  const env = { AUTH_TOKEN: token, Sandbox: {} };
  const allowExec = opts.allowExec ?? process.env.NEXUS_BROWSER_ALLOW_EXEC === '1';

  const toRequest = (req: http.IncomingMessage, body?: Buffer) => new Request(`http://127.0.0.1${req.url}`, {
    method: req.method, headers: req.headers as Record<string, string>,
    ...(body && body.length && req.method !== 'GET' && req.method !== 'HEAD' ? { body } : {}),
  });

  const server = http.createServer(async (req, res) => {
    const chunks: Buffer[] = [];
    for await (const c of req) chunks.push(c as Buffer);
    try {
      const u = new URL(req.url ?? '/', 'http://127.0.0.1'); const path = u.pathname;
      if (path === '/viewer') {
        if (!(await signedLive(u, token))) { res.writeHead(403); res.end('invalid or expired live link'); return; }
        res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' }); res.end(VIEWER(u.search.slice(1))); return;
      }
      if (path.startsWith('/stdb/')) {
        if (req.headers.authorization !== `Bearer ${token}`) { res.writeHead(401); res.end('{"error":"Unauthorized"}'); return; }
        const [status, json] = store.handle(path.slice(5), Buffer.concat(chunks).toString('utf8'));
        res.writeHead(status, { 'Content-Type': 'application/json' }); res.end(JSON.stringify(json)); return;
      }
      if (EXEC_PATHS.test(path) && !allowExec) {
        res.writeHead(403, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'run_command / run_code execute on this machine and are off by default. Set NEXUS_BROWSER_ALLOW_EXEC=1 (or allowExec: true) to enable them.' }));
        return;
      }
      const r: Response = await (sandboxWorker as any).fetch(toRequest(req, Buffer.concat(chunks)), env, { waitUntil() {} });
      const headers: Record<string, string> = {}; r.headers.forEach((v, k) => { headers[k] = v; });
      res.writeHead(r.status, headers);
      res.end(Buffer.from(await r.arrayBuffer()));
    } catch (e) {
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: String((e as Error)?.message ?? e).slice(0, 500) }));
    }
  });

  // Live view: let the Worker start x11vnc + websockify and name the port, then splice the client's socket onto websockify.
  server.on('upgrade', async (req, socket, head) => {
    try {
      const u = new URL(req.url ?? '/', 'http://127.0.0.1');
      if (u.pathname === '/live' && !req.headers.authorization) {
        const session = await signedLive(u, token);
        if (!session) { socket.end('HTTP/1.1 403 Forbidden\r\n\r\ninvalid or expired live link'); return; }
        req.headers.authorization = `Bearer ${token}`; req.headers['x-sandbox-session'] = session;
      }
      const r: Response = await (sandboxWorker as any).fetch(toRequest(req), env, { waitUntil() {} });
      const port = Number(r.headers.get('x-local-ws-port'));
      if (r.status !== 426 || !port) { socket.end(`HTTP/1.1 ${r.status} ${r.statusText}\r\n\r\n${await r.text()}`); return; }
      const upstream = net.connect(port, '127.0.0.1', () => {
        const lines = [`${req.method} ${req.url} HTTP/1.1`, ...Object.entries(req.headers).flatMap(([k, v]) => (Array.isArray(v) ? v : [v]).map((x) => `${k}: ${x}`))];
        upstream.write(lines.join('\r\n') + '\r\n\r\n'); if (head?.length) upstream.write(head);
        upstream.pipe(socket); socket.pipe(upstream);
      });
      upstream.on('error', () => socket.destroy()); socket.on('error', () => upstream.destroy());
    } catch { socket.destroy(); }
  });

  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
  const { port } = server.address() as net.AddressInfo;
  return { url: `http://127.0.0.1:${port}`, token, close: async () => { await stopLocalSandboxProcesses(); await new Promise<void>((r) => server.close(() => r())); } };
}
