/**
 * Local stand-ins for the Worker's Cloudflare storage: the Durable Object's SQL storage (ctx.storage.sql.exec — saved logins) on
 * Node's built-in SQLite, and a KV namespace (env.API_KEYS — recipes, telemetry) as a JSON file. Both live under one data
 * directory (default ~/.nexus-cortex/browser), created owner-only.
 */
import fs from 'node:fs';
import path from 'node:path';
import { DatabaseSync } from 'node:sqlite';

export function sqlStorage(file: string) {
  fs.mkdirSync(path.dirname(file), { recursive: true, mode: 0o700 });
  const db = new DatabaseSync(file);
  return {
    exec(query: string, ...bindings: unknown[]) {
      const stmt = db.prepare(query);
      const reads = /^\s*(select|with|pragma)\b/i.test(query);
      const rows: any[] = reads ? (stmt.all(...(bindings as any[])) as any[]) : (stmt.run(...(bindings as any[])), []);
      return Object.assign(rows, { toArray: () => rows, one: () => rows[0] ?? null, rowsRead: rows.length, rowsWritten: reads ? 0 : 1 });
    },
  };
}

export function fileKV(file: string) {
  fs.mkdirSync(path.dirname(file), { recursive: true, mode: 0o700 });
  type Entry = { v: string; exp?: number };
  const load = (): Record<string, Entry> => { try { return JSON.parse(fs.readFileSync(file, 'utf8')); } catch { return {}; } };
  const save = (d: Record<string, Entry>) => fs.writeFileSync(file, JSON.stringify(d), { mode: 0o600 });
  const live = (e?: Entry) => e && (!e.exp || e.exp > Date.now());
  return {
    async get(key: string, type?: string | { type?: string }) {
      const e = load()[key]; if (!live(e)) return null;
      const t = typeof type === 'string' ? type : type?.type;
      return t === 'json' ? JSON.parse(e!.v) : e!.v;
    },
    async put(key: string, value: string, opts?: { expirationTtl?: number; expiration?: number }) {
      const d = load(); const exp = opts?.expirationTtl ? Date.now() + opts.expirationTtl * 1000 : opts?.expiration ? opts.expiration * 1000 : undefined;
      d[key] = { v: typeof value === 'string' ? value : JSON.stringify(value), ...(exp ? { exp } : {}) }; save(d);
    },
    async delete(key: string) { const d = load(); delete d[key]; save(d); },
    async list(opts?: { prefix?: string; limit?: number; cursor?: string }) {
      const keys = Object.entries(load()).filter(([k, e]) => live(e) && (!opts?.prefix || k.startsWith(opts.prefix))).map(([name]) => ({ name })).sort((a, b) => a.name.localeCompare(b.name));
      return { keys: keys.slice(0, opts?.limit ?? 1000), list_complete: true, cursor: '' };
    },
  };
}
