/**
 * Local stand-in for the SpacetimeDB calls the browser Worker's workflow store makes (src/recipes.ts → STDB_SENSE_URL):
 *   POST /stdb/sql                         — SELECT … FROM web_recipe WHERE host = '…'   (STDB JSON result shape)
 *   POST /stdb/call/upsert_web_recipe        [id, host, kind, fingerprint, recipe_json, source, promoted]
 *   POST /stdb/call/record_web_recipe_outcome [id, success, note]
 *   POST /stdb/call/record_npc_decision      (any args — kept as JSON)
 * Same rules as the hosted reducers (modules/nexus-sense/spacetimedb-module/src/reducers/web_recipe.rs): score = Laplace
 * (s+1)/(s+f+2), new recipes start at 0.5, promoted at ≥2 successes and score ≥ 0.6, demoted at ≥3 attempts and score < 0.4.
 * Banked workflows stay in the user's own data directory.
 */
import fs from 'node:fs';
import path from 'node:path';
import { DatabaseSync } from 'node:sqlite';

const COLS = ['recipe_id', 'host', 'kind', 'fingerprint', 'recipe_json', 'successes', 'failures', 'score', 'promoted', 'source', 'updated_at'];

export function localStore(dataDir: string) {
  fs.mkdirSync(dataDir, { recursive: true, mode: 0o700 });
  const db = new DatabaseSync(path.join(dataDir, 'workflows.sqlite'));
  db.exec(`CREATE TABLE IF NOT EXISTS web_recipe (recipe_id TEXT PRIMARY KEY, host TEXT, kind TEXT, fingerprint TEXT, recipe_json TEXT,
    successes INTEGER DEFAULT 0, failures INTEGER DEFAULT 0, score REAL DEFAULT 0.5, promoted INTEGER DEFAULT 0, source TEXT,
    created_at INTEGER, updated_at INTEGER, last_success_at INTEGER DEFAULT 0, last_note TEXT DEFAULT '');
    CREATE TABLE IF NOT EXISTS decisions (id INTEGER PRIMARY KEY AUTOINCREMENT, at INTEGER, args TEXT);`);
  const laplace = (s: number, f: number) => (s + 1) / (s + f + 2);

  const reducers: Record<string, (a: any[]) => void> = {
    upsert_web_recipe([id, host, kind, fingerprint, recipe_json, source, promoted]) {
      const now = Date.now();
      const row = db.prepare('SELECT recipe_id FROM web_recipe WHERE recipe_id = ?').get(id);
      if (row) db.prepare('UPDATE web_recipe SET recipe_json = ?, fingerprint = ?, source = ?, updated_at = ?, promoted = CASE WHEN ? THEN 1 ELSE promoted END WHERE recipe_id = ?')
        .run(String(recipe_json), String(fingerprint), String(source), now, promoted ? 1 : 0, id);
      else db.prepare('INSERT INTO web_recipe (recipe_id, host, kind, fingerprint, recipe_json, source, promoted, created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?)')
        .run(id, host, kind, String(fingerprint), String(recipe_json), String(source), promoted ? 1 : 0, now, now);
    },
    record_web_recipe_outcome([id, success, note]) {
      const r = db.prepare('SELECT successes, failures, promoted FROM web_recipe WHERE recipe_id = ?').get(id) as any;
      if (!r) throw new Error(`no recipe ${id}`);
      const s = r.successes + (success ? 1 : 0), f = r.failures + (success ? 0 : 1), score = laplace(s, f);
      let promoted = r.promoted;
      if (s >= 2 && score >= 0.6) promoted = 1;
      if (s + f >= 3 && score < 0.4) promoted = 0;
      db.prepare('UPDATE web_recipe SET successes = ?, failures = ?, score = ?, promoted = ?, updated_at = ?, last_note = ?, last_success_at = CASE WHEN ? THEN ? ELSE last_success_at END WHERE recipe_id = ?')
        .run(s, f, score, promoted, Date.now(), String(note ?? ''), success ? 1 : 0, Date.now(), id);
    },
    record_npc_decision(args) { db.prepare('INSERT INTO decisions (at, args) VALUES (?, ?)').run(Date.now(), JSON.stringify(args)); },
  };

  return {
    /** Handle a /stdb/… request; returns [status, json body]. */
    handle(subPath: string, body: string): [number, unknown] {
      if (subPath === '/sql') {
        const host = /FROM web_recipe WHERE host = '([^']*)'/i.exec(body)?.[1];
        if (host === undefined) return [400, { error: 'the local store only answers the web_recipe query' }];
        const rows = (db.prepare(`SELECT ${COLS.join(', ')} FROM web_recipe WHERE host = ?`).all(host) as any[]).map((r) => COLS.map((c) => (c === 'promoted' ? !!r[c] : r[c])));
        return [200, [{ schema: { elements: COLS.map((c) => ({ name: { some: c } })) }, rows }]];
      }
      const m = /^\/call\/([a-z_]+)$/.exec(subPath);
      if (m && reducers[m[1]]) {
        let args: any; try { args = JSON.parse(body || '[]'); } catch { return [400, { error: 'bad JSON' }]; }
        try { reducers[m[1]](Array.isArray(args) ? args : [args]); return [200, {}]; } catch (e) { return [530, { error: String((e as Error).message) }]; }
      }
      return [404, { error: `the local store has no ${subPath}` }];
    },
  };
}
