/**
 * proxy.ts — residential egress for the browser MCP (2026-10-20).
 * Design: nexus-terminal/docs/research/vast-proxy-pool-design-2026-10-20.md §3 (data path) + §5 (limits).
 *
 * Pure helpers (rule matching, exclusions, host picking, STDB row decoding) live here so they are unit-testable; the Durable
 * Object (mcp.ts) owns the session state and the sandbox (sandbox-page.ts) opens the tunnel.
 *
 * Rules are the Browserbase-compatible table: first match per request hostname wins; no match → direct.
 *   { type: "vast",     country: "US", state?: "CA", domainPattern?: "*.example.com" }   → a pool host (SSH SOCKS tunnel)
 *   { type: "external", server: "http://host:port", username?, password?, domainPattern? } → any proxy Chrome accepts
 *   { type: "none",     domainPattern?: "*.internal" }                                   → direct, explicitly
 * Phase 1 = ONE proxy per browser context (the rule that matches the browse() URL); per-request domain routing is phase 2.
 */

export type ProxyRule =
  | { type: 'vast'; country: string; state?: string; domainPattern?: string; strictCountry?: boolean }
  | { type: 'external'; server: string; username?: string; password?: string; domainPattern?: string }
  | { type: 'none'; domainPattern?: string };

export interface ProxyHost {
  hostId: string;
  armId: string;
  country: string;
  state: string;
  sshHost: string | null;
  sshPort: number | null;
  egressIp: string | null;
  netClass: string | null;
  tunnels: number;
  tunnelsMax: number;
  dph: number;
}

/** Egress classes a browser session may be routed through (design §4: datacenter and unknown are never handed out). */
export const PROXY_OK_CLASSES = new Set(['residential', 'isp']);

/** The bench run that holds the pool (one arm per country, arm_id = `<run>:<CC>`). */
export const PROXY_POOL_RUN_ID = 'proxy-pool';

/** How long the picker's view of bench_host may be stale (KV cache). */
export const PROXY_HOST_CACHE_TTL_S = 60;

