/** Hostname of a URL (lower-case, no port); null when unparsable. */
export function hostnameOf(url: string): string | null {
  try { return new URL(url).hostname.toLowerCase().replace(/\.$/, ''); } catch { return null; }
}

/**
 * Does `pattern` cover `host`? undefined/empty → every host. `*` is a wildcard over any run of characters; a pattern without
 * `*` matches the host itself or any subdomain of it (dot boundary): `example.com` covers `www.example.com`, not `notexample.com`.
 */
export function domainMatches(pattern: string | undefined, host: string): boolean {
  if (!pattern || !pattern.trim()) return true;
  const p = pattern.trim().toLowerCase(), h = host.toLowerCase();
  if (p.includes('*')) {
    const re = new RegExp('^' + p.split('*').map(s => s.replace(/[.+?^${}()|[\]\\]/g, '\\$&')).join('.*') + '$');
    return re.test(h);
  }
  const bare = p.replace(/^\./, '');
  return h === bare || h.endsWith('.' + bare);
}

/** True when the host (or any parent domain) is on the exclusion list. */
export function isExcludedHost(host: string): boolean {
  const h = host.toLowerCase();
  return PROXY_EXCLUDED_DOMAINS.some(d => d.startsWith('.') ? (h.endsWith(d) || h === d.slice(1)) : (h === d || h.endsWith('.' + d)));
}

/** The rule that routes `host`: exclusions force `none`; else the first rule whose domainPattern covers it; null = direct. */
export function matchProxyRule(rules: readonly ProxyRule[], host: string): ProxyRule | null {
  if (isExcludedHost(host)) return { type: 'none', domainPattern: '(excluded domain)' };
  for (const r of rules) if (domainMatches(r.domainPattern, host)) return r;
  return null;
}

/** Validate a rules payload (anything the model sends). Returns the normalized rules and every problem found. */
export function validateProxyRules(input: unknown): { rules: ProxyRule[]; errors: string[] } {
  const errors: string[] = []; const rules: ProxyRule[] = [];
  if (!Array.isArray(input)) return { rules, errors: ['rules must be an array'] };
  if (input.length > 20) errors.push('at most 20 rules');
  input.slice(0, 20).forEach((raw, i) => {
    const r = (raw && typeof raw === 'object') ? raw as Record<string, unknown> : {};
    const type = String(r.type || '');
    const dp = r.domainPattern === undefined ? undefined : String(r.domainPattern);
    if (dp !== undefined && (dp.length > 200 || /[\s/]/.test(dp))) { errors.push(`rule ${i}: bad domainPattern`); return; }
    if (type === 'vast') {
      const country = String(r.country || '').toUpperCase();
      if (!/^[A-Z]{2}$/.test(country)) { errors.push(`rule ${i}: vast needs a 2-letter country`); return; }
      const state = r.state === undefined ? undefined : String(r.state).toUpperCase().slice(0, 3);
      rules.push({ type: 'vast', country, ...(state ? { state } : {}), ...(dp ? { domainPattern: dp } : {}), ...(r.strictCountry === true ? { strictCountry: true } : {}) });
    } else if (type === 'external') {
      const server = String(r.server || '');
      if (!/^(https?|socks5h?|socks4a?):\/\/[^\s/]+$/i.test(server)) { errors.push(`rule ${i}: external needs server = scheme://host:port`); return; }
      rules.push({ type: 'external', server, ...(r.username ? { username: String(r.username) } : {}),
        ...(r.password ? { password: String(r.password) } : {}), ...(dp ? { domainPattern: dp } : {}) });
    } else if (type === 'none') {
      rules.push({ type: 'none', ...(dp ? { domainPattern: dp } : {}) });
    } else {
      errors.push(`rule ${i}: type must be vast | external | none`);
    }
  });
  return { rules, errors };
}

/** The SQL the worker runs against the bench module (`STDB_BENCH_SQL_URL`). Column order = `decodeBenchHostRows`. */
export function proxyHostsSql(runId = PROXY_POOL_RUN_ID): string {
  return `SELECT host_id, arm_id, state, ssh_host, ssh_port, egress_ip, net_class, heartbeat_json, dph_total FROM bench_host WHERE run_id = '${runId}'`;
}

/** SpacetimeDB HTTP SQL encodes Option<T> as [0, v] (Some) / [1, []] (None); plain values come as-is. */
function unwrapOpt(v: unknown): unknown {
  if (v == null) return null;
  if (Array.isArray(v)) return v[0] === 0 && v[1] != null ? v[1] : null;
  return v;
}

/** Decode the rows of `proxyHostsSql` into ProxyHost records (a junk row is skipped, never thrown). */
export function decodeBenchHostRows(rows: unknown[][]): ProxyHost[] {
  const out: ProxyHost[] = [];
  for (const row of rows) {
    try {
      const armId = String(row[1] ?? '');
      const hbRaw = unwrapOpt(row[7]);
      let tunnels = 0, tunnelsMax = 0, hbClass: string | null = null, hbIp: string | null = null;
      if (typeof hbRaw === 'string' && hbRaw.startsWith('{')) {
        try {
          const hb = JSON.parse(hbRaw);
          tunnels = Number(hb.tunnels) || 0; tunnelsMax = Number(hb.tunnels_max) || 0;
          if (typeof hb.net_class === 'string') hbClass = hb.net_class.toLowerCase();
          if (typeof hb.egress_ip === 'string') hbIp = hb.egress_ip;
        } catch { /* keep zeros */ }
      }
      const netClass = unwrapOpt(row[6]); const egressIp = unwrapOpt(row[5]);
      const port = unwrapOpt(row[4]); const sshHost = unwrapOpt(row[3]); const dph = unwrapOpt(row[8]);
      out.push({
        hostId: String(row[0] ?? ''), armId, country: armId.includes(':') ? armId.split(':').pop()!.toUpperCase() : '',
        state: String(row[2] ?? ''),
        sshHost: typeof sshHost === 'string' && sshHost ? sshHost : null,
        sshPort: port == null ? null : Number(port) || null,
        egressIp: typeof egressIp === 'string' && egressIp ? egressIp : hbIp,
        netClass: typeof netClass === 'string' && netClass ? netClass.toLowerCase() : hbClass,
        tunnels, tunnelsMax, dph: typeof dph === 'number' ? dph : Number(dph) || 0,
      });
    } catch { /* skip */ }
  }
  return out;
}

/**
 * The host a `vast` rule gets: running, right country, residential/isp egress, an SSH endpoint, below its tunnel cap, fewest
 * tunnels first (then cheapest). `exclude` = hosts that just failed to open a tunnel this session.
 */
export function pickProxyHost(hosts: readonly ProxyHost[], rule: Extract<ProxyRule, { type: 'vast' }>, exclude?: ReadonlySet<string>, anyCountry = false): ProxyHost | null {
  const ok = hosts.filter(h => h.state === 'running' && (anyCountry || h.country === rule.country.toUpperCase())
    && h.netClass !== null && PROXY_OK_CLASSES.has(h.netClass) && !!h.sshHost && !!h.sshPort
    && (h.tunnelsMax === 0 || h.tunnels < h.tunnelsMax) && !(exclude?.has(h.hostId)));
  ok.sort((a, b) => a.tunnels - b.tunnels || a.dph - b.dph || a.hostId.localeCompare(b.hostId));
  return ok[0] ?? null;
}

/** 2026-11-12: a host that failed to open a tunnel (e.g. 'Permission denied (publickey)': a box whose authorized_keys lost the CA line
 *  while its heartbeat still said sshd_ok) is remembered POOL-WIDE in KV for this long, so every session skips it until host_watch
 *  replaces it — before, the exclusion lived only in the failing session and every new session hit the same dead host. */
export const PROXY_BAD_HOST_TTL_S = 900;
const badHostKey = (hostId: string) => `proxy-bad:${hostId}`;
export async function readBadProxyHosts(env: { API_KEYS?: KVNamespace }, hosts: readonly ProxyHost[]): Promise<Set<string>> {
  const bad = new Set<string>(); if (!env.API_KEYS) return bad;
  await Promise.all(hosts.map(async h => { try { if (await env.API_KEYS!.get(badHostKey(h.hostId))) bad.add(h.hostId); } catch { /* best effort */ } }));
  return bad;
}
export async function markBadProxyHost(env: { API_KEYS?: KVNamespace }, hostId: string, reason: string): Promise<void> {
  if (!env.API_KEYS) return;
  try { await env.API_KEYS.put(badHostKey(hostId), JSON.stringify({ reason: reason.slice(0, 300), at: Date.now() }), { expirationTtl: PROXY_BAD_HOST_TTL_S }); } catch { /* best effort */ }
}

/** Why no host was picked, for the error the model sees (counts per filter stage). */
export function explainNoHost(hosts: readonly ProxyHost[], rule: Extract<ProxyRule, { type: 'vast' }>): string {
  const cc = rule.country.toUpperCase();
  const inCountry = hosts.filter(h => h.country === cc);
  const running = inCountry.filter(h => h.state === 'running');
  const classed = running.filter(h => h.netClass !== null && PROXY_OK_CLASSES.has(h.netClass));
  const withSsh = classed.filter(h => h.sshHost && h.sshPort);
  const free = withSsh.filter(h => h.tunnelsMax === 0 || h.tunnels < h.tunnelsMax);
  return `no_proxy_host_for_region ${cc}: pool hosts ${hosts.length}, in country ${inCountry.length}, running ${running.length}, residential/isp ${classed.length}, with ssh endpoint ${withSsh.length}, below tunnel cap ${free.length}`;
}

/** A free local port for a new tunnel (1081..1099), avoiding the ones in use. */
export function nextLocalPort(used: Iterable<number>): number {
  const taken = new Set(used);
  for (let p = 1081; p < 1100; p++) if (!taken.has(p)) return p;
  return 1081;
}

/** Load the pool from the bench module over HTTP SQL (KV-cached for PROXY_HOST_CACHE_TTL_S). */
export async function loadProxyHosts(
  env: { STDB_BENCH_SQL_URL?: string; STDB_TOKEN?: string; API_KEYS?: KVNamespace },
  opts?: { fresh?: boolean; runId?: string },
): Promise<{ hosts: ProxyHost[]; source: 'kv' | 'stdb' | 'none'; error?: string }> {
  const runId = opts?.runId ?? PROXY_POOL_RUN_ID;
  const cacheKey = `proxy:hosts:${runId}`;
  if (!opts?.fresh && env.API_KEYS) {
    try {
      const raw = await env.API_KEYS.get(cacheKey);
      if (raw) return { hosts: JSON.parse(raw) as ProxyHost[], source: 'kv' };
    } catch { /* fall through */ }
  }
  if (!env.STDB_BENCH_SQL_URL || !env.STDB_TOKEN) return { hosts: [], source: 'none', error: 'STDB_BENCH_SQL_URL / STDB_TOKEN not configured' };
  try {
    const resp = await fetch(env.STDB_BENCH_SQL_URL, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${env.STDB_TOKEN}`, 'Content-Type': 'text/plain' },
      body: proxyHostsSql(runId),
    });
    if (!resp.ok) return { hosts: [], source: 'none', error: `STDB ${resp.status}` };
    const results = await resp.json() as Array<{ rows: unknown[][] }>;
    const hosts = decodeBenchHostRows(results[0]?.rows ?? []);
    if (env.API_KEYS) { try { await env.API_KEYS.put(cacheKey, JSON.stringify(hosts), { expirationTtl: PROXY_HOST_CACHE_TTL_S }); } catch { /* best effort */ } }
    return { hosts, source: 'stdb' };
  } catch (e) {
    return { hosts: [], source: 'none', error: String((e as Error)?.message || e).slice(0, 200) };
  }
}

/** The per-key policy (edge-supplied via ctx.props; `PROXY_DEFAULT_ALLOWED=true` relaxes it for a pilot). */
export function proxyPolicy(props: unknown, env: { PROXY_DEFAULT_ALLOWED?: string }): { allowed: boolean; dailySeconds: number; source: string } {
  const p = (props && typeof props === 'object') ? props as Record<string, unknown> : null;
  if (p && typeof p.proxyAllowed === 'boolean') {
    return { allowed: p.proxyAllowed, dailySeconds: Number(p.proxyDailySeconds) || 0, source: 'key' };
  }
  const def = String(env.PROXY_DEFAULT_ALLOWED || '').toLowerCase() === 'true';
  return { allowed: def, dailySeconds: 0, source: def ? 'env-default' : 'default-deny' };
}

/** Strip credentials before a rule is echoed back to the model or written to a trace. */
export function redactRules(rules: readonly ProxyRule[]): ProxyRule[] {
  return rules.map(r => r.type === 'external' ? { ...r, ...(r.password ? { password: '***' } : {}) } : r);
}
