/**
 * NexusSense React DevTools hook SHIM (pre-load injectable, 2026-10-19)
 *
 * React only registers itself with a DevTools hook that already exists when it boots:
 * it reads window.__REACT_DEVTOOLS_GLOBAL_HOOK__, calls hook.inject(internals) and then
 * reports every commit through hook.onCommitFiberRoot(rendererId, root). Without a hook
 * present BEFORE React loads, bippy-lite's renderer path (hook.renderers → findFiberByHostInstance)
 * is empty and it falls back to the per-element __reactFiber$ keys, which see nodes but not roots.
 *
 * This shim installs the minimal hook surface React 16–19 expects, records the injected
 * renderers and every committed root, and stays out of the way when a real DevTools hook
 * is already installed. Injected via evaluateOnNewDocument (puppeteer) / the relay's
 * /api/init_script (sandbox) BEFORE bippy-lite, so the first commit is captured.
 *
 * Exposed on the hook: renderers (Map), _nexusRoots (Set of FiberRoot), _nexusCommits,
 * _nexusLastCommitAt, getFiberRoots(). ZERO imports — a self-contained IIFE string.
 */

export const REACT_HOOK_SHIM_SCRIPT = `(function () {
  try {
    if (typeof window === 'undefined') return;
    if (window.__REACT_DEVTOOLS_GLOBAL_HOOK__) return; // real DevTools (or an earlier shim) wins
    var renderers = new Map();
    var roots = new Set();
    var listeners = {};
    var nextId = 0;
    function emit(event, data) {
      var fns = listeners[event];
      if (!fns) return;
      for (var i = 0; i < fns.length; i++) { try { fns[i](data); } catch (e) {} }
    }
    var hook = {
      __nexusShim: true,
      isDisabled: false,
      supportsFiber: true,
      supportsFlight: false,
      renderers: renderers,
      _nexusRoots: roots,
      _nexusCommits: 0,
      _nexusLastCommitAt: 0,
      inject: function (renderer) {
        var id = ++nextId;
        renderers.set(id, renderer);
        emit('renderer', { id: id, renderer: renderer });
        return id;
      },
      on: function (event, fn) { (listeners[event] = listeners[event] || []).push(fn); },
      off: function (event, fn) {
        var fns = listeners[event]; if (!fns) return;
        var i = fns.indexOf(fn); if (i >= 0) fns.splice(i, 1);
      },
      sub: function (event, fn) { hook.on(event, fn); return function () { hook.off(event, fn); }; },
      emit: emit,
      onCommitFiberRoot: function (rendererId, root) {
        if (root) roots.add(root);
        hook._nexusCommits++;
        hook._nexusLastCommitAt = Date.now();
        emit('commit', { rendererId: rendererId, root: root });
      },
      onPostCommitFiberRoot: function () {},
      onCommitFiberUnmount: function () {},
      onScheduleFiberRoot: function () {},
      setStrictMode: function () {},
      checkDCE: function () {},
      registerInternalModuleStart: function () {},
      registerInternalModuleStop: function () {},
      getFiberRoots: function () { return roots; }
    };
    Object.defineProperty(window, '__REACT_DEVTOOLS_GLOBAL_HOOK__', {
      value: hook, configurable: true, enumerable: false, writable: true
    });
  } catch (e) { /* never break the page */ }
})();`;
