// Web workflow corpus client (2026-10-20): read-through cache of the SpacetimeDB `web_recipe` table (module nexus-nexus-sense)
// and write-back of outcomes through its reducers. Structure only — never values, credentials or cookies.
export interface WebRecipe { recipe_id: string; host: string; kind: 'consent' | 'form' | 'challenge' | 'playbook' | 'search'; fingerprint: string; recipe: any; successes: number; failures: number; score: number; promoted: boolean; source: string; updated_at: number }
export interface RecipeEnv { STDB_SENSE_URL?: string; STDB_TOKEN?: string; API_KEYS?: KVNamespace }

const CACHE_TTL_S = 60;
function base(env: RecipeEnv): string | null { return env.STDB_SENSE_URL ? env.STDB_SENSE_URL.replace(/\/$/, '') : null; }

/** One row of the STDB /sql JSON result → WebRecipe (column order = the SELECT below). */
export function decodeRecipeRow(r: any[]): WebRecipe | null {
  if (!Array.isArray(r) || r.length < 10) return null;
  let recipe: any = null; try { recipe = JSON.parse(String(r[4] ?? '{}')); } catch { recipe = null; }
  return { recipe_id: String(r[0]), host: String(r[1]), kind: String(r[2]) as WebRecipe['kind'], fingerprint: String(r[3]), recipe, successes: Number(r[5]) || 0, failures: Number(r[6]) || 0, score: Number(r[7]) || 0, promoted: r[8] === true || r[8] === 'true', source: String(r[9] ?? ''), updated_at: Number(r[10]) || 0 };
}

export const RECIPE_SQL = (host: string) => `SELECT recipe_id, host, kind, fingerprint, recipe_json, successes, failures, score, promoted, source, updated_at FROM web_recipe WHERE host = '${host.replace(/'/g, '')}'`;

/** Recipes for a host: KV cache (60 s) in front of the STDB /sql endpoint. Never throws. */
export async function loadRecipes(env: RecipeEnv, host: string, opts: { fresh?: boolean } = {}): Promise<{ recipes: WebRecipe[]; source: 'cache' | 'stdb' | 'none'; error?: string }> {
  const h = (host || '').toLowerCase(); if (!h) return { recipes: [], source: 'none' };
  const ck = `recipes:${h}`;
  if (!opts.fresh && env.API_KEYS) { try { const c = await env.API_KEYS.get(ck, 'json') as { at: number; recipes: WebRecipe[] } | null; if (c && Date.now() - c.at < CACHE_TTL_S * 1000) return { recipes: c.recipes, source: 'cache' }; } catch { /* fall through */ } }
  const b = base(env); if (!b || !env.STDB_TOKEN) return { recipes: [], source: 'none', error: 'STDB_SENSE_URL / STDB_TOKEN not configured' };
  try {
    const resp = await fetch(`${b}/sql`, { method: 'POST', headers: { Authorization: `Bearer ${env.STDB_TOKEN}`, 'Content-Type': 'text/plain' }, body: RECIPE_SQL(h), signal: AbortSignal.timeout(6000) });
    if (!resp.ok) return { recipes: [], source: 'none', error: `stdb ${resp.status}` };
    const data: any = await resp.json();
    const rows: any[] = Array.isArray(data) && data[0]?.rows ? data[0].rows : [];
    const recipes = rows.map(decodeRecipeRow).filter((x): x is WebRecipe => !!x && !!x.recipe);
    if (env.API_KEYS) { try { await env.API_KEYS.put(ck, JSON.stringify({ at: Date.now(), recipes }), { expirationTtl: 600 }); } catch { /* cache is best-effort */ } }
    return { recipes, source: 'stdb' };
  } catch (e: any) { return { recipes: [], source: 'none', error: String(e?.message || e).slice(0, 120) }; }
}

async function call(env: RecipeEnv, reducer: string, args: unknown[]): Promise<{ ok: boolean; error?: string }> {
  const b = base(env); if (!b || !env.STDB_TOKEN) return { ok: false, error: 'not configured' };
  try {
    const resp = await fetch(`${b}/call/${reducer}`, { method: 'POST', headers: { Authorization: `Bearer ${env.STDB_TOKEN}`, 'Content-Type': 'application/json' }, body: JSON.stringify(args), signal: AbortSignal.timeout(6000) });
    if (!resp.ok) return { ok: false, error: `${resp.status} ${(await resp.text()).slice(0, 160)}` };
    return { ok: true };
  } catch (e: any) { return { ok: false, error: String(e?.message || e).slice(0, 120) }; }
}

/** Stable id for a recipe. */
export function recipeId(kind: WebRecipe['kind'], host: string, fingerprint: string): string { return `${kind}:${host.toLowerCase()}:${fingerprint}`; }

/** Small deterministic hash for fingerprints (FNV-1a, hex). */
export function fnv(s: string): string { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16).padStart(8, '0'); }

/** Upsert + bank an outcome in one go (used on a verified success/failure). Invalidates the host cache. */
export async function bankRecipe(env: RecipeEnv, r: { kind: WebRecipe['kind']; host: string; fingerprint: string; recipe: unknown; success: boolean; note?: string; source?: string }): Promise<{ recipe_id: string; ok: boolean; error?: string }> {
  const host = r.host.toLowerCase(); const id = recipeId(r.kind, host, r.fingerprint);
  const up = await call(env, 'upsert_web_recipe', [id, host, r.kind, r.fingerprint, JSON.stringify(r.recipe).slice(0, 16000), r.source || 'learned:nexus-browser', false]);
  if (!up.ok) return { recipe_id: id, ok: false, error: up.error };
  const oc = await call(env, 'record_web_recipe_outcome', [id, r.success, (r.note || '').slice(0, 200)]);
  if (env.API_KEYS) { try { await env.API_KEYS.delete(`recipes:${host}`); } catch { /* best effort */ } }
  return { recipe_id: id, ok: oc.ok, error: oc.error };
}

/** Outcome only (a known recipe was applied). */
export async function recordOutcome(env: RecipeEnv, recipe_id: string, success: boolean, note = ''): Promise<{ ok: boolean; error?: string }> {
  const r = await call(env, 'record_web_recipe_outcome', [recipe_id, success, note.slice(0, 200)]);
  const host = recipe_id.split(':')[1]; if (host && env.API_KEYS) { try { await env.API_KEYS.delete(`recipes:${host}`); } catch { /* */ } }
  return r;
}

/** The `_recipes` hint block for tool results: promoted first, then by score. */
export function recipeHints(recipes: WebRecipe[], kinds?: WebRecipe['kind'][]): Array<{ recipe_id: string; kind: string; confidence: number; promoted: boolean; outcomes: string; hint: string }> {
  return recipes.filter(r => !kinds || kinds.includes(r.kind)).sort((a, b) => Number(b.promoted) - Number(a.promoted) || b.score - a.score).slice(0, 6).map(r => ({
    recipe_id: r.recipe_id, kind: r.kind, confidence: Math.round(r.score * 100) / 100, promoted: r.promoted, outcomes: `${r.successes}✓/${r.failures}✗`,
    hint: r.kind === 'playbook' ? `banked workflow "${String(r.recipe?.intent || '').slice(0, 60)}": ${Array.isArray(r.recipe?.steps) ? r.recipe.steps.length : '?'} steps — ${Array.isArray(r.recipe?.steps) ? r.recipe.steps.slice(0, 4).map((st: any) => `${st.op} ${st.target || ''}`.trim()).join(' → ') : ''}` : r.kind === 'consent' ? `dismiss_overlays will try ${r.recipe?.selector || 'the banked selector'} first` : r.kind === 'form' ? `fill_form knows ${Array.isArray(r.recipe?.fields) ? r.recipe.fields.length : '?'} fields; submit via ${r.recipe?.submit?.text || r.recipe?.submit?.selector || '?'}` : r.kind === 'challenge' ? `${r.recipe?.vendor || '?'} ${r.recipe?.family || ''}: ${r.recipe?.method || '?'}` : `${r.recipe?.intent || r.fingerprint}: ${Array.isArray(r.recipe?.steps) ? r.recipe.steps.length + ' steps' : 'playbook'}`,
  }));
}

// ── Workflow store (2026-10-25, operator: "banking all workflow actions and decisions in their respective stores … like the Mind2Web
// store"). A workflow = the redacted action trail of a session on one host, banked as a `playbook` recipe keyed by its intent.
export interface WorkflowStep { op: string; target?: string; value?: string; path?: string }
const STOP = new Set(['the', 'a', 'an', 'to', 'for', 'of', 'in', 'on', 'and', 'with', 'my', 'me', 'i', 'it', 'this', 'that']);
export function intentTokens(intent: string): string[] {
  return String(intent || '').toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').split(/\s+/).filter(w => w.length > 2 && !STOP.has(w));
}
/** Stable fingerprint for an intent: its sorted content words. */
export function intentFingerprint(intent: string): string { return fnv([...new Set(intentTokens(intent))].sort().join(' ')); }
/** Banked playbooks ranked by word overlap with the agent's intent (top 3, overlap ≥ 1 word). */
export function learnedPlaybooks(recipes: WebRecipe[], intent: string): Array<{ recipe_id: string; intent: string; steps: WorkflowStep[]; outcomes: string; promoted: boolean; overlap: number }> {
  const want = new Set(intentTokens(intent)); if (!want.size) return [];
  return recipes.filter(r => r.kind === 'playbook' && r.recipe && Array.isArray(r.recipe.steps)).map(r => {
    const have = new Set(intentTokens(r.recipe.intent || '')); let overlap = 0; for (const w of want) if (have.has(w)) overlap++;
    return { recipe_id: r.recipe_id, intent: String(r.recipe.intent || '').slice(0, 120), steps: r.recipe.steps.slice(0, 40), outcomes: `${r.successes}✓/${r.failures}✗`, promoted: r.promoted, overlap };
  }).filter(x => x.overlap > 0).sort((a, b) => Number(b.promoted) - Number(a.promoted) || b.overlap - a.overlap).slice(0, 3);
}

// ── Decision store (the nexus-nexus-cortex decision lake, reducer record_npc_decision; same owner token, sibling database). ──
export interface DecisionEvent { kind: string; agent: string; data: unknown; model?: string; summary: string }
function cortexBase(env: RecipeEnv): string | null { const b = base(env); return b ? b.replace(/\/database\/[^/]+$/, '/database/nexus-nexus-cortex') : null; }
/** Durable, structure-only decision row. Never throws; returns the id or null. */
export async function recordDecision(env: RecipeEnv, ev: DecisionEvent): Promise<string | null> {
  const b = cortexBase(env); if (!b || !env.STDB_TOKEN) return null;
  const id = `bmcp-${Date.now().toString(36)}-${crypto.randomUUID().slice(0, 8)}`;
  try {
    const resp = await fetch(`${b}/call/record_npc_decision`, { method: 'POST', headers: { Authorization: `Bearer ${env.STDB_TOKEN}`, 'Content-Type': 'application/json' },
      body: JSON.stringify([id, `browser-mcp:${ev.agent}`, ev.kind, JSON.stringify(ev.data ?? {}).slice(0, 4000), ev.model || 'none', String(ev.summary || '').slice(0, 200), 0, 0]), signal: AbortSignal.timeout(6000) });
    return resp.ok ? id : null;
  } catch { return null; }
}
