/**
 * Playbook System — Pre-warming agent actions from Mind2Web training data.
 *
 * Before the agent starts interacting with a page, we check if we have
 * known action patterns for this domain or task category. If so, we return
 * a "playbook" — a compact sequence of expected actions and element hints
 * that the agent can follow or use as reference.
 *
 * Two matching levels:
 *   1. Domain match — exact hostname lookup (e.g., "united.com" → airline booking patterns)
 *   2. Category match — semantic category from task intent (e.g., "book a flight" → travel patterns)
 *
 * Data source: Mind2Web (2,350 tasks, 137 websites, 31 domains)
 * Storage: Cloudflare KV with prefix `playbook:domain:` and `playbook:category:`
 */

// ─── Types ───────────────────────────────────────────────────────────────────

export interface PlaybookStep {
  /** Action type: CLICK, TYPE, SELECT, SCROLL */
  op: string;
  /** Human-readable description of the target element */
  target: string;
  /** Optional value (text to type, option to select) */
  value?: string;
  /** Element hints — tag, role, common attributes. NOT exact selectors (they go stale). */
  hints?: {
    tag?: string;
    role?: string;
    textContent?: string;
    attributes?: Record<string, string>;
  };
}

export interface PlaybookTask {
  /** Natural language task description (from Mind2Web "confirmed_task") */
  intent: string;
  /** Ordered action sequence */
  steps: PlaybookStep[];
}

export interface DomainPlaybook {
  /** Canonical domain (e.g., "united.com") */
  domain: string;
  /** High-level category (e.g., "travel/airlines") */
  category: string;
  /** Top-level domain from Mind2Web (Travel, Shopping, Service, Entertainment, Information) */
  topDomain: string;
  /** Known task patterns for this domain */
  tasks: PlaybookTask[];
}

export interface CategoryPlaybook {
  /** Category ID (e.g., "travel/airlines", "shopping/fashion") */
  category: string;
  topDomain: string;
  /** Generalized action patterns across all sites in this category */
  commonPatterns: {
    /** Pattern name (e.g., "search_flights", "add_to_cart") */
    name: string;
    /** Typical step sequence */
    steps: PlaybookStep[];
  }[];
  /** Domains covered by this category */
  domains: string[];
}

export interface PlaybookMatch {
  /** How the playbook was matched */
  matchType: 'domain' | 'category' | 'none';
  /** Confidence: 1.0 for exact domain, 0.3-0.9 for category */
  confidence: number;
  /** The domain or category that matched */
  matchKey: string;
  /** Relevant task patterns (top 3 most relevant) */
  tasks: PlaybookTask[];
  /** Category-level common patterns (if category match) */
  commonPatterns?: CategoryPlaybook['commonPatterns'];
  /** Compact text hint for the agent's system context */
  agentHint: string;
}

// ─── Category Keywords ───────────────────────────────────────────────────────
