// ─── Playbook Matcher ────────────────────────────────────────────────────────

/**
 * Look up a playbook for the given URL and optional task intent.
 * Checks KV for domain-level match first, then falls back to category matching.
 */
export async function matchPlaybook(
  kv: KVNamespace,
  url: string,
  taskIntent?: string,
): Promise<PlaybookMatch | null> {
  let hostname: string;
  try {
    hostname = new URL(url).hostname.replace(/^www\./, '');
  } catch {
    return null;
  }

  // ── Level 1: Exact domain match ──────────────────────────────────────────
  const domainKey = `playbook:domain:${hostname}`;
  const domainData = await kv.get<DomainPlaybook>(domainKey, 'json');

  if (domainData && domainData.tasks.length > 0) {
    // If we have a task intent, rank tasks by relevance
    let relevantTasks = domainData.tasks;
    if (taskIntent) {
      relevantTasks = rankTasksByIntent(domainData.tasks, taskIntent);
    }
    const topTasks = relevantTasks.slice(0, 3);

    return {
      matchType: 'domain',
      confidence: 1.0,
      matchKey: hostname,
      tasks: topTasks,
      agentHint: formatAgentHint('domain', hostname, domainData.category, topTasks),
    };
  }

  // ── Level 2: Category match from task intent ─────────────────────────────
  if (taskIntent) {
    const category = matchCategory(taskIntent);
    if (category) {
      const catKey = `playbook:category:${category}`;
      const catData = await kv.get<CategoryPlaybook>(catKey, 'json');

      if (catData) {
        return {
          matchType: 'category',
          confidence: scoreCategoryMatch(taskIntent, category),
          matchKey: category,
          tasks: catData.commonPatterns.map(p => ({
            intent: p.name,
            steps: p.steps,
          })),
          commonPatterns: catData.commonPatterns,
          agentHint: formatCategoryHint(category, catData),
        };
      }
    }
  }

  // ── Level 2b: Domain-to-category fallback ────────────────────────────────
  // Even without a task intent, check if the domain's TLD suggests a category
  const domainCategory = await kv.get<string>(`playbook:domain-category:${hostname}`);
  if (domainCategory) {
    const catKey = `playbook:category:${domainCategory}`;
    const catData = await kv.get<CategoryPlaybook>(catKey, 'json');
    if (catData) {
      return {
        matchType: 'category',
        confidence: 0.5,
        matchKey: domainCategory,
        tasks: catData.commonPatterns.map(p => ({
          intent: p.name,
          steps: p.steps,
        })),
        commonPatterns: catData.commonPatterns,
        agentHint: formatCategoryHint(domainCategory, catData),
      };
    }
  }

  return null;
}

// ─── Intent Matching Helpers ─────────────────────────────────────────────────

/** Match a task intent string to the best category via keyword overlap */
function matchCategory(intent: string): string | null {
  const lower = intent.toLowerCase();
  let bestCategory: string | null = null;
  let bestScore = 0;

  for (const [category, keywords] of Object.entries(CATEGORY_KEYWORDS)) {
    let score = 0;
    for (const kw of keywords) {
      if (lower.includes(kw)) {
        // Longer keyword matches are more specific → higher weight
        score += kw.length;
      }
    }
    if (score > bestScore) {
      bestScore = score;
      bestCategory = category;
    }
  }

  // Require minimum score to avoid false matches
  return bestScore >= 4 ? bestCategory : null;
}

/** Score how well a task intent matches a category (0-1) */
function scoreCategoryMatch(intent: string, category: string): number {
  const lower = intent.toLowerCase();
  const keywords = CATEGORY_KEYWORDS[category] || [];
  let matched = 0;
  for (const kw of keywords) {
    if (lower.includes(kw)) matched++;
  }
  // Normalize: 1 keyword = 0.3, 2 = 0.5, 3+ = 0.7-0.9
  return Math.min(0.3 + matched * 0.2, 0.9);
}

/** Rank tasks by keyword overlap with the intent */
function rankTasksByIntent(tasks: PlaybookTask[], intent: string): PlaybookTask[] {
  const lower = intent.toLowerCase();
  const words = new Set(lower.split(/\s+/).filter(w => w.length > 2));

  return [...tasks].sort((a, b) => {
    const scoreA = taskOverlap(a.intent, words);
    const scoreB = taskOverlap(b.intent, words);
    return scoreB - scoreA;
  });
}

function taskOverlap(taskIntent: string, intentWords: Set<string>): number {
  const taskLower = taskIntent.toLowerCase();
  let score = 0;
  for (const word of intentWords) {
    if (taskLower.includes(word)) score++;
  }
  return score;
}

// ─── Agent Hint Formatting ───────────────────────────────────────────────────
// Compact text injected into the browse result for the agent to read.

function formatAgentHint(
  matchType: string,
  matchKey: string,
  category: string,
  tasks: PlaybookTask[],
): string {
  const lines: string[] = [
    `[Playbook: ${matchKey} (${category})]`,
    `Known action patterns for this site:`,
  ];

  for (const task of tasks) {
    lines.push(`  "${task.intent}":`);
    for (let i = 0; i < task.steps.length; i++) {
      const s = task.steps[i];
      const val = s.value ? ` "${s.value}"` : '';
      const hint = s.hints?.textContent ? ` [text: "${s.hints.textContent}"]` : '';
      lines.push(`    ${i + 1}. ${s.op} → ${s.target}${val}${hint}`);
    }
  }

  lines.push(`Use scan() to find matching elements. Patterns may be outdated — verify before acting.`);
  return lines.join('\n');
}

function formatCategoryHint(category: string, catData: CategoryPlaybook): string {
  const lines: string[] = [
    `[Playbook: ${category} category pattern]`,
    `No exact site match, but this domain type typically follows these patterns:`,
  ];

  for (const pattern of catData.commonPatterns.slice(0, 3)) {
    lines.push(`  "${pattern.name}":`);
    for (let i = 0; i < pattern.steps.length; i++) {
      const s = pattern.steps[i];
      const val = s.value ? ` "${s.value}"` : '';
      lines.push(`    ${i + 1}. ${s.op} → ${s.target}${val}`);
    }
  }

  lines.push(`These are generalized patterns — scan() to find actual elements.`);
  return lines.join('\n');
}
