/**
 * The nexus-cortex secrets vault, seen from the browser library (docs/SECRETS_VAULT_PLAN.md Phase 3). OPTIONAL: loaded at runtime only
 * when @nexus-cortex/core is installed (it is next to every nexus-cortex harness); standalone, every function here is a no-op.
 *
 *  - helperKeys(): the Worker's helper keys — GOOGLE_API_KEY (Gemma decisions / vision; GEMINI_API_KEY accepted), TYPESAFE_API_KEY (Jev),
 *    INCEPTION_API_KEY (Mercury) — from explicit options, then the environment, then the vault. Only these names; never the whole vault.
 *  - set_proxy credentials by reference: the model writes `«secret:NAME»` (or `{{secret:NAME}}`) for a proxy username/password and the
 *    library substitutes the value before the Worker sees the rule. OPT-IN per secret: only secrets the user bound for this tool
 *    (`cortex secrets bind NAME NAME --tool nexus-browser`) resolve — the model chooses the proxy server, so an unrestricted reference
 *    would let a prompt-injected page route any vault value to an attacker's host. Values in the tool's result are masked back.
 */
export const BROWSER_TOOL_SCOPE = 'nexus-browser';
const HELPER_KEYS = ['GOOGLE_API_KEY', 'TYPESAFE_API_KEY', 'INCEPTION_API_KEY'] as const;
const REF = /«secret:([A-Za-z_][A-Za-z0-9_]*)»|\{\{\s*secret:([A-Za-z_][A-Za-z0-9_]*)\s*\}\}/g;

interface VaultLike { names(): string[]; get(n: string): string | null; bindings(): Array<{ secret: string; scope: string; tool?: string }> }
interface CoreLike { openVaultNonInteractive(): { vault: VaultLike | null }; maskSecrets(text: string, values: Array<{ name: string; value: string }>): string }

let core: CoreLike | null | undefined;
async function loadCore(): Promise<CoreLike | null> {
  if (core !== undefined) return core;
  const spec = '@nexus-cortex/core';   // a variable specifier: esbuild leaves it as a runtime import (optional dependency)
  try { core = (await import(spec)) as unknown as CoreLike; } catch { core = null; }
  return core;
}

async function openVault(): Promise<VaultLike | null> {
  const c = await loadCore(); if (!c) return null;
  try { return c.openVaultNonInteractive().vault; } catch { return null; }
}

/** Resolve «secret:NAME» references in a string (e.g. NEXUS_BROWSER_PROXY_URL for the browse wall escalation) with the secrets opted in
 *  for the browser. Returns null when a referenced secret is not available — the caller then leaves the feature off rather than sending a
 *  literal placeholder as a password. */
export async function resolveSecretRefs(text: string): Promise<string | null> {
  REF.lastIndex = 0; if (!REF.test(text)) { REF.lastIndex = 0; return text; } REF.lastIndex = 0;
  const allowed = await browserSecrets(); let missing = false;
  const out = text.replace(REF, (_m, a, b) => { const v = allowed.get(a || b); if (v === undefined) { missing = true; return ''; } return encodeURIComponent(v); });
  return missing ? null : out;
}

/** Helper keys for the Worker env: explicit options > environment > vault. */
export async function helperKeys(explicit: Record<string, string | undefined> = {}, env: NodeJS.ProcessEnv = process.env): Promise<Record<string, string>> {
  const out: Record<string, string> = {};
  const vault = await openVault();
  const pick = (k: string) => explicit[k] || env[k] || vault?.get(k) || undefined;
  for (const k of HELPER_KEYS) { const v = pick(k) || (k === 'GOOGLE_API_KEY' ? pick('GEMINI_API_KEY') : undefined); if (v) out[k] = v; }
  return out;
}

/** Secrets the user opted in for the browser tool (bound with --tool nexus-browser). */
async function browserSecrets(): Promise<Map<string, string>> {
  const vault = await openVault(); const out = new Map<string, string>();
  if (!vault) return out;
  for (const b of vault.bindings()) if (b.scope === 'tool' && b.tool === BROWSER_TOOL_SCOPE) { const v = vault.get(b.secret); if (v) out.set(b.secret, v); }
  return out;
}

/** Replace secret references in every string of `value` (deep). Unknown / not-opted-in names are collected, not resolved. */
function substitute(value: unknown, allowed: Map<string, string>, refused: Set<string>): unknown {
  if (typeof value === 'string') return value.replace(REF, (m, a, b) => { const n = (a || b) as string; const v = allowed.get(n); if (v === undefined) { refused.add(n); return m; } return v; });
  if (Array.isArray(value)) return value.map((x) => substitute(x, allowed, refused));
  if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([k, x]) => [k, substitute(x, allowed, refused)]));
  return value;
}

type Handler = (args: any, extra: any) => Promise<any> | any;

/** Wrap set_proxy on an McpServer (SDK ≥1.2x keeps handlers in _registeredTools[name].handler, looked up per call). */
export function wrapSetProxyForVault(server: any): boolean {
  const tool = server?._registeredTools?.set_proxy;
  if (!tool || typeof tool.handler !== 'function') return false;
  const inner: Handler = tool.handler;
  tool.handler = async (args: any, extra: any) => {
    const raw = JSON.stringify(args ?? {});
    if (!REF.test(raw)) { REF.lastIndex = 0; return inner(args, extra); }
    REF.lastIndex = 0;
    const allowed = await browserSecrets(); const refused = new Set<string>();
    const resolved = substitute(args, allowed, refused);
    if (refused.size) {
      const names = [...refused].join(', ');
      return { isError: true, content: [{ type: 'text', text: `Secret reference(s) not available to the browser: ${names}. The user must store the value in the nexus-cortex secrets vault and opt it in for this tool: \`cortex secrets set NAME\` then \`cortex secrets bind NAME NAME --tool ${BROWSER_TOOL_SCOPE}\`.` }] };
    }
    const result = await inner(resolved, extra);
    const c = await loadCore(); const values = [...allowed].map(([name, value]) => ({ name, value }));
    if (!c || !values.length || !Array.isArray(result?.content)) return result;
    return { ...result, content: result.content.map((p: any) => (p?.type === 'text' && typeof p.text === 'string' ? { ...p, text: c.maskSecrets(p.text, values) } : p)) };
  };
  return true;
}
