/**
 * NexusBrowser Sandbox — Real Chrome in a Linux Container
 *
 * Uses the base cloudflare/sandbox image with pre-installed
 * Chromium, Xvfb, xdotool, and a persistent Playwright Python relay.
 *
 * Architecture:
 *   Playwright relay (Python) — persistent CDP connection, browser lifecycle,
 *     JS evaluation, screenshots, cookies, waiting
 *   xdotool (OS-level) — human-like mouse/keyboard input, undetectable
 *
 * The relay eliminates per-call overhead: no more spawning node processes,
 * opening fresh WebSockets, or installing npm packages at runtime.
 */

import { getSandbox, proxyToSandbox, Sandbox as SandboxClass } from '@cloudflare/sandbox';
export { Sandbox } from '@cloudflare/sandbox';

interface Env {
  // Properly type the DO namespace so getSandbox()/proxyToSandbox() type-check.
  // Without the generic, tsc reports DurableObjectNamespace<undefined> mismatching
  // the SandboxEnv<Sandbox<any>> the SDK helpers expect.
  Sandbox: DurableObjectNamespace<SandboxClass<any>>;
  AUTH_TOKEN?: string;
}

const DISPLAY = ':99';
const RESOLUTION = '1280x800x24';
const RELAY_URL = 'http://127.0.0.1:8222';
const INTERPRETER_URL = 'http://127.0.0.1:8223';

const CORS_HEADERS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization',
};

function json(data: unknown, status = 200): Response {
  return Response.json(data, { status, headers: CORS_HEADERS });
}

function err(message: string, status = 400): Response {
  return json({ error: message }, status);
}

type SandboxLike = {
  exec: (cmd: string, opts?: { timeout?: number }) => Promise<{
    stdout: string; stderr: string; exitCode: number; success: boolean;
  }>;
  writeFile?: (path: string, content: string) => Promise<unknown>;
};

/** Bodies larger than this reach the relay / interpreter through a temp FILE instead of the command line (2026-10-25): the hex-on-argv
 *  path doubles the size and one argv string is capped (~128 KB, MAX_ARG_STRLEN), so bigger bodies arrived EMPTY ("script required") —
 *  e.g. load_auth's localStorage restore (refresh token + layouts) silently wrote nothing, and big run_code payloads failed the same way. */
const ARGV_BODY_MAX = 48 * 1024;
async function postLargeBody(sandbox: SandboxLike, url: string, bodyJson: string, timeout: number, label: string): Promise<any> {
  const f = `/tmp/body-${Date.now()}-${Math.random().toString(36).slice(2, 8)}.json`;
  await sandbox.writeFile!(f, bodyJson);
  const r = await sandbox.exec(`curl -s --max-time ${Math.ceil(timeout / 1000)} -X POST -H 'Content-Type: application/json' --data-binary @${f} ${url}; rm -f ${f}`, { timeout: timeout + 5000 });
  try { return JSON.parse(r.stdout.trim()); } catch { return { error: r.stderr || r.stdout || `${label} call failed` }; }
}

// ─── Relay communication ───────────────────────────────────────────────────

/**
 * Call the Playwright relay server inside the sandbox.
 * Uses curl for simplicity — relay is on localhost, latency is ~1ms.
 */
async function relayCall(
  sandbox: SandboxLike,
  endpoint: string,
  body?: Record<string, unknown>,
  timeout = 30000,
): Promise<any> {
  const method = body !== undefined ? 'POST' : 'GET';
  let cmd: string;

  if (method === 'GET') {
    cmd = `curl -s --max-time ${Math.ceil(timeout / 1000)} ${RELAY_URL}${endpoint}`;
  } else {
    // Hex-encode the JSON body to avoid shell escaping issues.
    // Decode with python3 (xxd is not available in the container image).
    const bodyJson = JSON.stringify(body);
    if (bodyJson.length > ARGV_BODY_MAX && typeof sandbox.writeFile === 'function') return postLargeBody(sandbox, `${RELAY_URL}${endpoint}`, bodyJson, timeout, 'relay');
    const hex = Array.from(new TextEncoder().encode(bodyJson))
      .map(b => b.toString(16).padStart(2, '0')).join('');
    cmd = `python3 -c "import sys;sys.stdout.buffer.write(bytes.fromhex('${hex}'))" | curl -s --max-time ${Math.ceil(timeout / 1000)} -X POST -H 'Content-Type: application/json' -d @- ${RELAY_URL}${endpoint}`;
  }

  const result = await sandbox.exec(cmd, { timeout: timeout + 5000 });

  try {
    return JSON.parse(result.stdout.trim());
  } catch {
    return { error: result.stderr || result.stdout || 'relay call failed' };
  }
}

/**
 * Ensure the Playwright relay is running. Starts it if not.
 */
async function ensureRelay(sandbox: SandboxLike): Promise<boolean> {
  // Quick health check
  const check = await sandbox.exec(
    `curl -s --max-time 2 ${RELAY_URL}/health 2>/dev/null || echo "NOT_RUNNING"`,
    { timeout: 5000 },
  );

  if (!check.stdout.includes('NOT_RUNNING') && check.stdout.includes('"status"')) {
    return true;
  }

  // The relay is down → the container was (re)started, e.g. after its 5-minute idle stop. Xvfb died with it, and /api/setup only runs
  // once per session, so start the display here too — otherwise Chrome fails with "Missing X server or $DISPLAY" (2026-10-25).
  const xv = await sandbox.exec(`pgrep -f "Xvfb ${DISPLAY}" >/dev/null && echo up || echo down`, { timeout: 5000 });
  if (xv.stdout.includes('down')) {
    await sandbox.exec(`Xvfb ${DISPLAY} -screen 0 ${RESOLUTION} -ac +extension GLX +render -noreset &`, { timeout: 5000 });
    await sleep(1000);
  }

  // Start the relay in the background
  await sandbox.exec(
    `DISPLAY=${DISPLAY} PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH=/usr/bin/google-chrome-stable ` +
    `python3 /opt/playwright-relay.py &`,
    { timeout: 5000 },
  );

  // Wait for it to come up (max 5s)
  for (let i = 0; i < 10; i++) {
    await sleep(500);
    const probe = await sandbox.exec(
      `curl -s --max-time 1 ${RELAY_URL}/health 2>/dev/null || echo "NOT_READY"`,
      { timeout: 3000 },
    );
    if (!probe.stdout.includes('NOT_READY') && probe.stdout.includes('"status"')) {
      return true;
    }
  }

  return false;
}

/**
 * Ensure the code interpreter is running. Starts it if not.
 */
async function ensureInterpreter(sandbox: SandboxLike): Promise<boolean> {
  const check = await sandbox.exec(
    `curl -s --max-time 2 ${INTERPRETER_URL}/health 2>/dev/null || echo "NOT_RUNNING"`,
    { timeout: 5000 },
  );

  if (!check.stdout.includes('NOT_RUNNING') && check.stdout.includes('"status"')) {
    return true;
  }

  await sandbox.exec(`python3 /opt/code-interpreter.py &`, { timeout: 5000 });

  for (let i = 0; i < 6; i++) {
    await sleep(500);
    const probe = await sandbox.exec(
      `curl -s --max-time 1 ${INTERPRETER_URL}/health 2>/dev/null || echo "NOT_READY"`,
      { timeout: 3000 },
    );
    if (!probe.stdout.includes('NOT_READY') && probe.stdout.includes('"status"')) {
      return true;
    }
  }

  return false;
}

/** Hex-encode a string for a safe `python3 -c bytes.fromhex` round-trip through the exec shell (no quoting hazards). */
function toHex(str: string): string {
  return Array.from(new TextEncoder().encode(str)).map(b => b.toString(16).padStart(2, '0')).join('');
}

const PROXY_DIR = '/tmp/nexus-proxy';

/**
 * Call the code interpreter server inside the sandbox.
 */
async function interpreterCall(
  sandbox: SandboxLike,
  endpoint: string,
  body?: Record<string, unknown>,
  timeout = 30000,
): Promise<any> {
  const method = body !== undefined ? 'POST' : 'GET';
  let cmd: string;

  if (method === 'GET') {
    cmd = `curl -s --max-time ${Math.ceil(timeout / 1000)} ${INTERPRETER_URL}${endpoint}`;
  } else {
    const bodyJson = JSON.stringify(body);
    if (bodyJson.length > ARGV_BODY_MAX && typeof sandbox.writeFile === 'function') return postLargeBody(sandbox, `${INTERPRETER_URL}${endpoint}`, bodyJson, timeout, 'interpreter');
    const hex = Array.from(new TextEncoder().encode(bodyJson))
      .map(b => b.toString(16).padStart(2, '0')).join('');
    cmd = `python3 -c "import sys;sys.stdout.buffer.write(bytes.fromhex('${hex}'))" | curl -s --max-time ${Math.ceil(timeout / 1000)} -X POST -H 'Content-Type: application/json' -d @- ${INTERPRETER_URL}${endpoint}`;
  }

  const result = await sandbox.exec(cmd, { timeout: timeout + 5000 });

  try {
    return JSON.parse(result.stdout.trim());
  } catch {
    return { error: result.stderr || result.stdout || 'interpreter call failed' };
  }
}

// ─── Main handler ──────────────────────────────────────────────────────────

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    if (request.method === 'OPTIONS') {
      return new Response(null, { status: 204, headers: CORS_HEADERS });
    }

    // Auth check — FAIL CLOSED. A missing/empty AUTH_TOKEN (secret never set,
    // or cleared) must lock the worker, not skip the gate. Latent today (this
    // worker is private: no workers_dev, reached only via nexus-browser's
    // service binding) but the guard removes the "add a route later → silently
    // open" footgun. Defense-in-depth alongside the binding isolation.
    if (!env.AUTH_TOKEN) {
      return err('AUTH_TOKEN not configured — refusing all requests (fail-closed)', 503);
    }
    const auth = request.headers.get('Authorization');
    if (auth !== `Bearer ${env.AUTH_TOKEN}`) {
      return err('Unauthorized', 401);
    }

    // Proxy preview URLs
    const proxyResponse = await proxyToSandbox(request, env);
    if (proxyResponse) return proxyResponse;

    const url = new URL(request.url);
    // Session-based sandbox isolation: each MCP session gets its own container.
    // Falls back to 'default' for direct API usage without a session header.
    const rawSessionId = request.headers.get('X-Sandbox-Session') || url.searchParams.get('session') || 'default';
    // Container name limit is 63 chars. "nexus-browser-" prefix = 14 chars, so session ID max = 49.
    const sessionId = rawSessionId.slice(0, 49);
    const sandbox = getSandbox(env.Sandbox, `nexus-browser-${sessionId}`, {
      sleepAfter: '5m', // Auto-stop container after 5 min idle (saves billing)
    });
    const path = url.pathname;

    try {
      // ─── Live view (2.9.3) ───────────────────────────────────────────
      // WebSocket into the container's VNC (x11vnc on the Xvfb display, bridged by websockify). Reached only through
      // nexus-browser's signed, session-scoped /live route (this request already passed the AUTH_TOKEN check above).
      if (path === '/live' && request.headers.get('Upgrade')?.toLowerCase() === 'websocket') {
        const xvfb = await sandbox.exec(`pgrep -f "Xvfb ${DISPLAY}" >/dev/null && echo up || echo down`);
        if (!xvfb.stdout.includes('up')) {
          return err('No browser display in this session yet — browse with backend "sandbox" first', 409);
        }
        await sandbox.exec(
          // x11vnc stays localhost-only; websockify must listen on the container's network address because
          // sandbox.wsConnect proxies to it from outside the container (10.0.0.1:6080) — reachable only through this
          // AUTH_TOKEN-gated route. Wait (≤ 5 s) until the port actually listens before connecting.
          `pgrep -x x11vnc >/dev/null || x11vnc -display ${DISPLAY} -forever -shared -nopw -localhost -rfbport 5900 -quiet -bg -o /tmp/x11vnc.log; ` +
          `pgrep -f "websockify.*6080" >/dev/null || (nohup websockify 0.0.0.0:6080 127.0.0.1:5900 >/tmp/websockify.log 2>&1 &); ` +
          `for i in $(seq 1 25); do (exec 3<>/dev/tcp/127.0.0.1/6080) 2>/dev/null && break; sleep 0.2; done`,
          { timeout: 12000 },
        );
        return sandbox.wsConnect(request, 6080);
      }

      // ─── Setup (start Xvfb + Playwright relay) ───────────────────────

      if (path === '/api/setup' && request.method === 'POST') {
        // Deps are pre-baked in Dockerfile. Just verify and start services.
        const status: string[] = [];

        // Check pre-baked deps — search common paths + PATH
        const check = await sandbox.exec(
          'echo "chromium:$(which google-chrome-stable 2>/dev/null || which google-chrome 2>/dev/null || which chromium 2>/dev/null || which chromium-browser 2>/dev/null || ls /usr/bin/google-chrome* 2>/dev/null || ls /usr/bin/chromium* 2>/dev/null || echo MISSING)" && ' +
          'echo "xdotool:$(which xdotool 2>/dev/null || echo MISSING)" && ' +
          'echo "python3:$(which python3 2>/dev/null || echo MISSING)" && ' +
          'echo "PATH:$PATH"',
        );
        const checkOutput = check.stdout.trim();

        if (checkOutput.includes('chromium:MISSING')) {
          return err(`Chrome/Chromium not found in container. Debug: ${checkOutput.slice(0, 500)}`, 500);
        }
        if (checkOutput.includes('xdotool:MISSING')) {
          return err('xdotool not found in container image. Dockerfile may need rebuild.', 500);
        }

        // Start Xvfb if not running
        const xvfbCheck = await sandbox.exec(`pgrep -f "Xvfb ${DISPLAY}" || echo "NOT_RUNNING"`);
        if (xvfbCheck.stdout.includes('NOT_RUNNING')) {
          await sandbox.exec(
            `Xvfb ${DISPLAY} -screen 0 ${RESOLUTION} -ac +extension GLX +render -noreset &`,
            { timeout: 5000 },
          );
          await sleep(1000);
          status.push('xvfb-started');
        } else {
          status.push('xvfb-already-running');
        }

        // Start Playwright relay if not running
        const relayUp = await ensureRelay(sandbox);
        status.push(relayUp ? 'relay-started' : 'relay-failed');

        // Verify display
        const verify = await sandbox.exec(
          `DISPLAY=${DISPLAY} xdotool getdisplaygeometry 2>&1`,
        );

        return json({
          success: relayUp,
          status,
          display: verify.stdout.trim(),
          resolution: RESOLUTION,
        });
      }

      // ─── Status ───────────────────────────────────────────────────────

      if (path === '/api/status') {
        const xvfb = await sandbox.exec(`pgrep -f "Xvfb ${DISPLAY}" && echo "running" || echo "stopped"`);
        const relay = await sandbox.exec(
          `curl -s --max-time 1 ${RELAY_URL}/health 2>/dev/null || echo '{"status":"stopped"}'`,
        );
        let relayStatus: any = { status: 'stopped' };
        try { relayStatus = JSON.parse(relay.stdout.trim()); } catch {}

        return json({
          xvfb: xvfb.stdout.includes('running') ? 'running' : 'stopped',
          relay: relayStatus,
        });
      }

      // ─── Browse (navigate to URL) ─────────────────────────────────────

      if (path === '/api/browse' && request.method === 'POST') {
        const body = await request.json<{ url: string; waitUntil?: string; timeout?: number }>();
        if (!body.url) return err('url required');

        await ensureRelay(sandbox);

        const result = await relayCall(sandbox, '/navigate', {
          url: body.url,
          waitUntil: body.waitUntil ?? 'domcontentloaded',
          timeout: body.timeout ?? 30000,
        }, (body.timeout ?? 30000) + 5000);

        if (result.error) return json({ error: result.error }, 500);

        return json({
          success: true,
          url: result.url,
          title: result.title,
          screenshot: result.screenshot,
          screenshotFormat: result.screenshotFormat || 'jpeg',
        });
      }

      // ─── Detect Challenge ─────────────────────────────────────────────

      if (path === '/api/detect_challenge' && request.method === 'POST') {
        const evalResult = await relayCall(sandbox, '/evaluate', {
          script: `(() => {
            const title = document.title;
            const isChallenge = title.includes('Just a moment') ||
              title.includes('Attention Required') ||
              title.includes('Security Check');
            return { title, isChallenge };
          })()`,
        });

        const screenshotResult = await relayCall(sandbox, '/screenshot');

        return json({
          challengeDetected: evalResult?.result?.isChallenge ?? false,
          windowTitle: evalResult?.result?.title ?? 'unknown',
          screenshot: screenshotResult?.screenshot ?? null,
          screenshotFormat: 'jpeg',
          hint: evalResult?.result?.isChallenge
            ? 'Challenge detected. Use /api/click with approximate checkbox coordinates.'
            : 'No challenge detected.',
        });
      }

      // ─── Click (OS-level via xdotool) ─────────────────────────────────

      if (path === '/api/click' && request.method === 'POST') {
        const body = await request.json<{
          x: number; y: number;
          humanLike?: boolean;
          postClickWaitMs?: number;
        }>();
        if (body.x === undefined || body.y === undefined) return err('x and y required');

        const humanLike = body.humanLike !== false;
        const postWait = body.postClickWaitMs ?? 5000;

        // 2026-10-20: coordinates are PAGE coordinates. xdotool works in SCREEN space and the headed window's chrome sits above the
        // viewport (outerHeight - innerHeight ≈ 131 px), so every xdotool click landed above its target. Default = Playwright's mouse
        // through the relay (CDP, page space, human-like stepped approach); `xdotool: true` keeps the OS path with the offset applied.
        if ((body as any).xdotool === true) {
          const off = await windowOffset(sandbox);
          const sx = body.x + off.ox + off.sx, sy = body.y + off.oy + off.sy;
          if (humanLike) await humanMouseMove(sandbox, sx, sy); else { await sandbox.exec(`DISPLAY=${DISPLAY} xdotool mousemove ${sx} ${sy}`); await sleep(50); }
          await sandbox.exec(`DISPLAY=${DISPLAY} xdotool click 1`);
        } else {
          await ensureRelay(sandbox);
          const r = await relayCall(sandbox, '/mouse', { action: 'click', x: body.x, y: body.y, humanLike, button: (body as any).button || 'left', clickCount: (body as any).clickCount || 1 }, 15000);
          if (r?.error) return json({ error: r.error }, 500);
        }
        await sleep(postWait);

        // Screenshot + title via relay
        const [screenshot, title] = await Promise.all([
          relayCall(sandbox, '/screenshot'),
          relayCall(sandbox, '/evaluate', { script: 'document.title' }),
        ]);

        return json({
          clicked: { x: body.x, y: body.y },
          humanLike,
          windowTitle: title?.result ?? 'unknown',
          screenshot: screenshot?.screenshot ?? null,
          screenshotFormat: 'jpeg',
        });
      }

      // ─── Type Text (xdotool) ──────────────────────────────────────────

      if (path === '/api/type' && request.method === 'POST') {
        const body = await request.json<{ text: string; delayMs?: number }>();
        if (!body.text) return err('text required');

        const delay = body.delayMs ?? 80;
        const safeText = body.text.replace(/'/g, "'\\''");
        await sandbox.exec(
          `DISPLAY=${DISPLAY} xdotool type --delay ${delay} '${safeText}'`,
        );

        return json({ typed: body.text.length, success: true });
      }

      // ─── Key Press (xdotool) ──────────────────────────────────────────

      // 2026-11-02: keys go to the X-FOCUSED window — with nothing focused (no click yet) they went nowhere, so the Chrome window is
      // focused first. keydown/keyup are their own endpoints (they used /api/exec, which a LOCAL install refuses unless the user opts
      // in to command execution — every Ctrl/Shift/Alt combination silently failed there). Key names are X keysyms / xdotool combos only.
      const KEY_OK = /^[A-Za-z0-9_+]{1,40}$/;
      const FOCUS_CHROME = `DISPLAY=${DISPLAY} xdotool search --onlyvisible --class chrom 2>/dev/null | head -1 | xargs -r -I{} xdotool windowfocus {} 2>/dev/null; `;
      if (path === '/api/press' && request.method === 'POST') {
        const body = await request.json<{ key: string }>();
        if (!body.key) return err('key required');
        if (!KEY_OK.test(body.key)) return err('invalid key name');

        await sandbox.exec(`${FOCUS_CHROME}DISPLAY=${DISPLAY} xdotool key ${body.key}`);
        return json({ pressed: body.key, success: true });
      }

      if ((path === '/api/keydown' || path === '/api/keyup') && request.method === 'POST') {
        const body = await request.json<{ key: string }>();
        if (!body.key || !KEY_OK.test(body.key)) return err('invalid key name');
        await sandbox.exec(`${FOCUS_CHROME}DISPLAY=${DISPLAY} xdotool ${path === '/api/keydown' ? 'keydown' : 'keyup'} ${body.key}`);
        return json({ success: true });
      }

      // ─── Press-and-Hold (PerimeterX/HUMAN sustained-press challenges) ─
      // The whole gesture — flyTo-style eased Bezier approach + settle
      // wiggle + mousedown + jittered hold + mouseup — runs as a SINGLE
      // container-side bash script. We pre-compute every (x, y, sleep)
      // tuple in the worker (cubic Bezier with ease-in-out cubic
      // applied to t), then emit them as N consecutive
      // `xdotool mousemove X Y; sleep S` lines. ONE sandbox.exec call
      // total → exact timing, no HTTP overhead between steps.
      //
      // Earlier naive impl: 50+ separate worker→container HTTP roundtrips
      // padded a 4s hold to 14s+ with phantom motion PerimeterX flags.
      if (path === '/api/press_and_hold' && request.method === 'POST') {
        const body = await request.json<{
          x: number; y: number;
          holdMs?: number;
          jitterPx?: number;
          /** If true (default), prepend a flyTo-style Bezier approach
           *  before the press. Set false to skip (cursor already in
           *  position). */
          humanLikeApproach?: boolean;
        }>();
        if (body.x === undefined || body.y === undefined) return err('x and y required');

        const holdMs = Math.max(500, Math.min(15000, body.holdMs ?? 3500));
        // page → screen for the OS-level hold (2026-10-20)
        { const off = await windowOffset(sandbox); (body as any).x = Number(body.x) + off.ox + off.sx; (body as any).y = Number(body.y) + off.oy + off.sy; }
        const jitterPx = Math.max(0, Math.min(8, body.jitterPx ?? 2));
        const targetX = Math.round(body.x);
        const targetY = Math.round(body.y);

        // ── Build the full script in JS, then send as one exec ──────────
        const lines: string[] = [];

        // 1. Flyto-style eased Bezier approach (mirrors the camera fly
        //    semantics MAP/MapWindow uses for map.flyTo: ease-in-out
        //    cubic, slight overshoot avoided by ending exactly on
        //    target, settle wiggle before final stop).
        if (body.humanLikeApproach !== false) {
          const startX = targetX + Math.round((Math.random() - 0.5) * 280);
          const startY = targetY + Math.round((Math.random() - 0.5) * 220);
          // Bezier control points — slight perpendicular offset
          const cp1x = startX + (targetX - startX) * 0.3 + (Math.random() - 0.5) * 80;
          const cp1y = startY + (targetY - startY) * 0.3 + (Math.random() - 0.5) * 80;
          const cp2x = startX + (targetX - startX) * 0.7 + (Math.random() - 0.5) * 80;
          const cp2y = startY + (targetY - startY) * 0.7 + (Math.random() - 0.5) * 80;
          // Step count scales with distance (longer move = more samples)
          const dist = Math.hypot(targetX - startX, targetY - startY);
          const steps = Math.max(8, Math.min(20, Math.round(8 + dist / 60)));
          // Total flight duration ~ 350-700ms based on distance
          const flightMs = Math.max(350, Math.min(700, Math.round(dist * 1.4)));
          const stepDelayMs = Math.round(flightMs / steps);

          // Initial jump to start position + settle pause
          lines.push(`xdotool mousemove ${startX} ${startY}`);
          lines.push(`sleep ${(0.08 + Math.random() * 0.12).toFixed(3)}`);

          // ease-in-out cubic: slow-start, fast-middle, slow-end
          const ease = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);

          for (let i = 1; i <= steps; i++) {
            const t = ease(i / steps);
            const u = 1 - t;
            const mx = Math.round(u * u * u * startX + 3 * u * u * t * cp1x + 3 * u * t * t * cp2x + t * t * t * targetX);
            const my = Math.round(u * u * u * startY + 3 * u * u * t * cp1y + 3 * u * t * t * cp2y + t * t * t * targetY);
            lines.push(`xdotool mousemove ${mx} ${my}`);
            lines.push(`sleep ${(stepDelayMs / 1000).toFixed(3)}`);
          }

          // Settle wiggle — 3 tiny ±2px drifts before resting on target.
          // This mimics the way a real cursor settles (small overshoot
          // corrections rather than landing exactly on first frame).
          for (let i = 0; i < 3; i++) {
            const wx = targetX + Math.round((Math.random() - 0.5) * 4);
            const wy = targetY + Math.round((Math.random() - 0.5) * 4);
            lines.push(`xdotool mousemove ${wx} ${wy}`);
            lines.push(`sleep ${(0.04 + Math.random() * 0.04).toFixed(3)}`);
          }
          lines.push(`xdotool mousemove ${targetX} ${targetY}`);
          lines.push(`sleep ${(0.06 + Math.random() * 0.08).toFixed(3)}`);
        }

        // 2. Mousedown
        lines.push(`xdotool mousedown 1`);

        // 3. Hold loop with ±jitterPx drift, ~80ms per micro-move.
        //    Done as bash for-loop (RANDOM is a bash builtin), single
        //    process so the hold is uninterruptible.
        const stepCount = Math.max(1, Math.floor(holdMs / 80));
        const range = jitterPx * 2 + 1;
        const offset = jitterPx;
        lines.push(`for i in $(seq 1 ${stepCount}); do`);
        lines.push(`  dx=$((RANDOM % ${range} - ${offset}))`);
        lines.push(`  dy=$((RANDOM % ${range} - ${offset}))`);
        lines.push(`  xdotool mousemove $((${targetX} + dx)) $((${targetY} + dy))`);
        lines.push(`  sleep 0.08`);
        lines.push(`done`);

        // 4. Mouseup
        lines.push(`xdotool mouseup 1`);

        const script = lines.join('; ');

        const start = Date.now();
        await sandbox.exec(
          `DISPLAY=${DISPLAY} bash -c '${script}'`,
          { timeout: holdMs + 15000 },
        );
        const actualHoldMs = Date.now() - start;

        return json({
          pressed: { x: targetX, y: targetY },
          holdMs,
          actualHoldMs,
          stepCount,
          jitterPx,
          flytoApproach: body.humanLikeApproach !== false,
          scriptLines: lines.length,
          success: true,
        });
      }

      // ─── Screenshot (as image) ────────────────────────────────────────

      if (path === '/api/screenshot') {
        const result = await relayCall(sandbox, '/screenshot');
        if (result.error || !result.screenshot) {
          // Fallback to ImageMagick if relay isn't running
          await sandbox.exec(
            `DISPLAY=${DISPLAY} import -window root -quality 85 /tmp/screenshot.jpg`,
            { timeout: 10000 },
          );
          const b64 = await sandbox.exec('base64 -w0 /tmp/screenshot.jpg');
          const binary = atob(b64.stdout.trim());
          const bytes = new Uint8Array(binary.length);
          for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);

          return new Response(bytes, {
            headers: { 'Content-Type': 'image/jpeg', 'Cache-Control': 'no-store', ...CORS_HEADERS },
          });
        }

        const binary = atob(result.screenshot);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);

        return new Response(bytes, {
          headers: { 'Content-Type': 'image/jpeg', 'Cache-Control': 'no-store', ...CORS_HEADERS },
        });
      }

      // ─── Screenshot (as JSON) ─────────────────────────────────────────

      if (path === '/api/screenshot/json') {
        const result = await relayCall(sandbox, '/screenshot');
        if (result.error) {
          // Fallback to ImageMagick
          await sandbox.exec(
            `DISPLAY=${DISPLAY} import -window root -quality 80 /tmp/screenshot.jpg`,
            { timeout: 10000 },
          );
          const b64 = await sandbox.exec('base64 -w0 /tmp/screenshot.jpg');
          return json({ screenshot: b64.stdout.trim(), format: 'jpeg' });
        }
        return json({ screenshot: result.screenshot, format: 'jpeg' });
      }

      // ─── Execute Command ──────────────────────────────────────────────

      if (path === '/api/exec' && request.method === 'POST') {
        const body = await request.json<{ command: string; timeout?: number }>();
        if (!body.command) return err('command required');

        const result = await sandbox.exec(
          `DISPLAY=${DISPLAY} ${body.command}`,
          { timeout: body.timeout ?? 30000 },
        );

        return json({
          stdout: result.stdout,
          stderr: result.stderr,
          exitCode: result.exitCode,
          success: result.success,
        });
      }

      // ─── Code Interpreter: Execute ──────────────────────────────────

      if (path === '/api/interpret' && request.method === 'POST') {
        const body = await request.json<{
          language?: string;
          code: string;
          sessionId?: string;
          timeout?: number;
        }>();
        if (!body.code) return err('code required');

        await ensureInterpreter(sandbox);

        const timeout = Math.min(body.timeout ?? 30, 120);
        const result = await interpreterCall(sandbox, '/execute', {
          language: body.language ?? 'python',
          code: body.code,
          sessionId: body.sessionId ?? 'default',
          timeout,
        }, (timeout + 5) * 1000);

        if (result.error && !result.output && !result.returnValue) {
          return json({ error: result.error }, 500);
        }
        return json(result);
      }

      // ─── Code Interpreter: Reset Session ────────────────────────────

      if (path === '/api/interpret/reset' && request.method === 'POST') {
        const body = await request.json<{ language?: string; sessionId?: string }>();

        await ensureInterpreter(sandbox);

        const result = await interpreterCall(sandbox, '/reset', {
          language: body.language ?? 'python',
          sessionId: body.sessionId ?? 'default',
        });
        return json(result);
      }

      // ─── Code Interpreter: List Sessions ────────────────────────────

      if (path === '/api/interpret/sessions') {
        await ensureInterpreter(sandbox);
        const result = await interpreterCall(sandbox, '/sessions');
        return json(result);
      }

      // ─── Evaluate JS via Playwright relay ─────────────────────────────

      if (path === '/api/evaluate' && request.method === 'POST') {
        const body = await request.json<{ script: string; timeout?: number; isolatedContext?: boolean; frame?: number | string }>();
        if (!body.script) return err('script required');

        const result = await relayCall(sandbox, '/evaluate', {
          script: body.script,
          ...(body.isolatedContext === false ? { isolatedContext: false } : {}),
          ...(body.frame !== undefined && body.frame !== null ? { frame: body.frame } : {}),
        }, body.timeout ?? 30000);

        if (result.error) return json({ error: result.error }, 500);
        return json({ result: result.result ?? null });
      }

      // ─── Console capture (2026-10-28): the relay buffers console/pageerror/requestfailed/4xx-5xx since the page opened ───
      if (path === '/api/console' && request.method === 'POST') {
        const body = await request.json<{ since?: number; limit?: number; clear?: boolean; minRank?: number }>().catch(() => ({} as any));
        await ensureRelay(sandbox);
        const r = await relayCall(sandbox, '/console', body || {}, 15000);
        if (r?.error) return json({ error: r.error }, 500);
        return json({ total: r.total ?? 0, entries: r.entries || [] });
      }

      // ─── Frames + page-space mouse (2026-10-20) ─────────────────────────
      if (path === '/api/frames') {
        await ensureRelay(sandbox);
        const r = await relayCall(sandbox, '/frames', {}, 15000);
        if (r?.error) return json({ error: r.error }, 500);
        return json({ frames: r.frames || [] });
      }
      if (path === '/api/mouse' && request.method === 'POST') {
        const body = await request.json<{ action: string; x?: number; y?: number; button?: string; humanLike?: boolean; steps?: number }>();
        await ensureRelay(sandbox);
        const r = await relayCall(sandbox, '/mouse', body as any, 15000);
        if (r?.error) return json({ error: r.error }, 500);
        return json(r);
      }

      // ─── Generic CDP call via Playwright relay ─────────────────────────

      if (path === '/api/cdp' && request.method === 'POST') {
        const body = await request.json<{ method: string; params?: Record<string, unknown>; timeout?: number }>();
        if (!body.method) return err('method required');

        const result = await relayCall(sandbox, '/cdp', {
          method: body.method,
          params: body.params || {},
        }, body.timeout ?? 30000);

        if (result.error) return json({ error: result.error }, 500);
        return json(result);
      }

      // ─── Pre-load init script (context.add_init_script via relay) ──────
      // Runs BEFORE any page script on every new document; the worker's
      // SandboxPage.evaluateOnNewDocument() calls this for parity with puppeteer.

      if (path === '/api/init_script' && request.method === 'POST') {
        const body = await request.json<{ script: string; applyNow?: boolean; timeout?: number }>();
        if (!body.script || typeof body.script !== 'string') return err('script (string) required');

        const result = await relayCall(sandbox, '/init_script', {
          script: body.script,
          applyNow: body.applyNow ?? true,
        }, body.timeout ?? 30000);

        if (result.error) return json({ error: result.error }, 500);
        return json(result);
      }

      // ─── Set Cookies ──────────────────────────────────────────────────

      if (path === '/api/set_cookies' && request.method === 'POST') {
        const body = await request.json<{ cookies: any[] }>();
        if (!body.cookies?.length) return err('cookies array required');

        const result = await relayCall(sandbox, '/cookies/set', {
          cookies: body.cookies,
        });

        if (result.error) return json({ error: result.error }, 500);
        return json({ success: true, set: result.set, total: body.cookies.length });
      }

      // ─── Extract Cookies ──────────────────────────────────────────────

      if (path === '/api/extract_cookies' && request.method === 'POST') {
        const body = await request.json<{ domain?: string }>();

        const result = await relayCall(sandbox, '/cookies/get', {
          domain: body.domain || '',
        });

        if (result.error) return json({ error: result.error }, 500);
        return json({ cookies: result.cookies, count: result.count });
      }

      // ─── Scroll (xdotool) ─────────────────────────────────────────────

      if (path === '/api/scroll' && request.method === 'POST') {
        const body = await request.json<{
          x?: number; y?: number;
          direction: 'up' | 'down';
          clicks?: number;
        }>();

        const x = body.x ?? 640;
        const y = body.y ?? 400;
        const clicks = body.clicks ?? 3;
        const button = body.direction === 'up' ? 4 : 5;

        await sandbox.exec(`DISPLAY=${DISPLAY} xdotool mousemove ${x} ${y}`);
        for (let i = 0; i < clicks; i++) {
          await sandbox.exec(`DISPLAY=${DISPLAY} xdotool click ${button}`);
          await sleep(50);
        }

        return json({ scrolled: true, direction: body.direction, clicks });
      }

      // ─── Wait for Navigation ──────────────────────────────────────────

      if (path === '/api/wait_for_navigation' && request.method === 'POST') {
        const body = await request.json<{
          timeoutMs?: number;
          selector?: string;
          urlPattern?: string;
          state?: string;
          // Legacy params (still supported)
          expectTitleContains?: string;
          expectTitleNotContains?: string;
        }>();

        const timeout = body.timeoutMs ?? 30000;

        // If using Playwright-native wait params, use relay directly
        if (body.selector || body.urlPattern || body.state) {
          const result = await relayCall(sandbox, '/wait', {
            selector: body.selector,
            urlPattern: body.urlPattern,
            state: body.state,
            timeout,
          }, timeout + 5000);

          const screenshot = await relayCall(sandbox, '/screenshot');

          return json({
            ...result,
            screenshot: screenshot?.screenshot ?? null,
            screenshotFormat: 'jpeg',
          });
        }

        // Legacy polling mode (for title-based waiting)
        const poll = 1000;
        const start = Date.now();
        let polls = 0;
        let lastTitle = '';

        while (Date.now() - start < timeout) {
          polls++;
          await sleep(poll);

          const titleResult = await relayCall(sandbox, '/evaluate', {
            script: 'document.title',
          });
          const title = titleResult?.result ?? 'unknown';
          lastTitle = title;

          if (body.expectTitleContains && title.includes(body.expectTitleContains)) {
            const screenshot = await relayCall(sandbox, '/screenshot');
            return json({
              resolved: true, method: 'titleContains', polls,
              elapsedMs: Date.now() - start, windowTitle: title,
              screenshot: screenshot?.screenshot, screenshotFormat: 'jpeg',
            });
          }

          if (body.expectTitleNotContains && !title.includes(body.expectTitleNotContains)) {
            const screenshot = await relayCall(sandbox, '/screenshot');
            return json({
              resolved: true, method: 'titleChanged', polls,
              elapsedMs: Date.now() - start, windowTitle: title,
              screenshot: screenshot?.screenshot, screenshotFormat: 'jpeg',
            });
          }

          if (!body.expectTitleContains && !body.expectTitleNotContains) {
            if (!title.includes('Just a moment') && !title.includes('Security Check') && title !== 'unknown') {
              const screenshot = await relayCall(sandbox, '/screenshot');
              return json({
                resolved: true, method: 'challengeGone', polls,
                elapsedMs: Date.now() - start, windowTitle: title,
                screenshot: screenshot?.screenshot, screenshotFormat: 'jpeg',
              });
            }
          }
        }

        const screenshot = await relayCall(sandbox, '/screenshot');
        return json({
          resolved: false, method: 'timeout', polls,
          elapsedMs: Date.now() - start, windowTitle: lastTitle,
          screenshot: screenshot?.screenshot, screenshotFormat: 'jpeg',
        });
      }

      // ─── Full Turnstile Solve ─────────────────────────────────────────

      if (path === '/api/solve_turnstile' && request.method === 'POST') {
        const body = await request.json<{
          url: string;
          waitBeforeClickMs?: number;
          waitAfterClickMs?: number;
        }>();
        if (!body.url) return err('url required');

        const waitBefore = body.waitBeforeClickMs ?? 4000;
        const waitAfter = body.waitAfterClickMs ?? 8000;

        // Ensure Xvfb is running
        const xvfbCheck = await sandbox.exec(`pgrep -f "Xvfb ${DISPLAY}" || echo "NOT_RUNNING"`);
        if (xvfbCheck.stdout.includes('NOT_RUNNING')) {
          await sandbox.exec(`Xvfb ${DISPLAY} -screen 0 ${RESOLUTION} -ac +extension GLX +render -noreset &`);
          await sleep(1000);
        }

        // Ensure relay is running, then navigate
        await ensureRelay(sandbox);

        // Close existing page and navigate fresh
        await relayCall(sandbox, '/close', {});
        await sleep(300);
        const navResult = await relayCall(sandbox, '/launch', {
          url: body.url,
          timeout: 15000,
        }, 20000);

        await sleep(waitBefore);

        // Use Playwright to find the Turnstile checkbox
        const findResult = await relayCall(sandbox, '/evaluate', {
          script: `(() => {
            var iframe = document.querySelector('iframe[src*="challenges.cloudflare.com"], iframe[src*="turnstile"]');
            if (iframe) {
              var r = iframe.getBoundingClientRect();
              return { x: Math.round(r.x + 30), y: Math.round(r.y + r.height / 2), method: 'iframe', rect: { x: r.x, y: r.y, width: r.width, height: r.height } };
            }
            var container = document.querySelector('[class*="cf-turnstile"], .cf-turnstile, #cf-turnstile-container');
            if (container) {
              var r = container.getBoundingClientRect();
              return { x: Math.round(r.x + 30), y: Math.round(r.y + r.height / 2), method: 'container', rect: { x: r.x, y: r.y, width: r.width, height: r.height } };
            }
            var checkbox = document.querySelector('#challenge-running input[type="checkbox"], .challenge-platform input');
            if (checkbox) {
              var r = checkbox.getBoundingClientRect();
              return { x: Math.round(r.x + r.width / 2), y: Math.round(r.y + r.height / 2), method: 'checkbox', rect: { x: r.x, y: r.y, width: r.width, height: r.height } };
            }
            return null;
          })()`,
        });

        const cbLocation = findResult?.result;
        const cbX = cbLocation?.x ?? 210;
        const cbY = cbLocation?.y ?? 336;

        // Screenshot before click
        const beforeScreenshot = await relayCall(sandbox, '/screenshot');

        // Human-like mouse movement to checkbox (OS-level, undetectable)
        await humanMouseMove(sandbox, cbX, cbY);

        // Click via xdotool
        await sandbox.exec(`DISPLAY=${DISPLAY} xdotool click 1`);
        await sleep(waitAfter);

        // Screenshot after click
        const afterScreenshot = await relayCall(sandbox, '/screenshot');

        // Check if challenge passed
        const titleResult = await relayCall(sandbox, '/evaluate', {
          script: 'document.title',
        });
        const pageTitle = titleResult?.result || '';
        const challengePassed =
          !!pageTitle &&
          !pageTitle.includes('Just a moment') &&
          !pageTitle.includes('Security Check') &&
          !pageTitle.includes('Attention Required');

        return json({
          url: body.url,
          challengePassed,
          pageTitle,
          clickedAt: { x: cbX, y: cbY },
          clickMethod: cbLocation?.method ?? 'fallback',
          beforeScreenshot: beforeScreenshot?.screenshot,
          afterScreenshot: afterScreenshot?.screenshot,
          screenshotFormat: 'jpeg',
        });
      }

      // ─── Proxy tunnels (2026-10-20, residential egress pool) ───────────
      // design: nexus-terminal/docs/research/vast-proxy-pool-design-2026-10-20.md §3.
      // /api/proxy/open: start `ssh -N -D 127.0.0.1:<port>` to a pool host (the worker
      // passes the endpoint + its private key; the key file is removed once the tunnel is
      // up — ssh has it in memory). /api/launch {proxy} then relaunches Chrome through it.
      // Every exec here is short (<5 s): the container's exec session dies on long calls.

      if (path === '/api/proxy/open' && request.method === 'POST') {
        const body = await request.json<{ sshHost: string; sshPort: number; user?: string; key: string; cert?: string; localPort?: number; hostId?: string }>();
        if (!body.sshHost || !body.sshPort || !body.key) return err('sshHost, sshPort, key required');
        const port = Math.floor(Number(body.localPort) || 1080);
        if (!(port >= 1024 && port <= 65535)) return err('localPort must be 1024..65535');
        const host = String(body.sshHost).replace(/[^A-Za-z0-9_.:-]/g, '');
        const sshPort = Math.floor(Number(body.sshPort));
        const user = String(body.user || 'root').replace(/[^A-Za-z0-9_.-]/g, '');
        if (!host || !(sshPort > 0 && sshPort < 65536) || !user) return err('bad ssh endpoint');
        const key = body.key.endsWith('\n') ? body.key : body.key + '\n';
        const keyFile = `${PROXY_DIR}/${port}.key`, pidFile = `${PROXY_DIR}/${port}.pid`, logFile = `${PROXY_DIR}/${port}.log`;
        const hasSsh = await sandbox.exec('command -v ssh || echo MISSING', { timeout: 5000 });
        if (hasSsh.stdout.includes('MISSING')) return err('openssh-client is not in this container image (needs image >= 2.8.0)', 500);
        await sandbox.exec(
          `mkdir -p ${PROXY_DIR} && chmod 700 ${PROXY_DIR} && ( [ -f ${pidFile} ] && kill $(cat ${pidFile}) 2>/dev/null; rm -f ${pidFile} ${logFile}; true ) && ` +
          `umask 077 && python3 -c "import sys;sys.stdout.buffer.write(bytes.fromhex('${toHex(key)}'))" > ${keyFile} && chmod 600 ${keyFile}` +
          // 2026-10-22: a short-lived CA certificate for the ephemeral key (ssh loads <key>-cert.pub automatically)
          (body.cert ? ` && python3 -c "import sys;sys.stdout.buffer.write(bytes.fromhex('${toHex(String(body.cert).trim() + '\n')}'))" > ${keyFile}-cert.pub && chmod 600 ${keyFile}-cert.pub` : ''),
          { timeout: 8000 },
        );
        await sandbox.exec(
          `setsid nohup ssh -N -D 127.0.0.1:${port} -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o BatchMode=yes ` +
          `-o ServerAliveInterval=30 -o ServerAliveCountMax=3 -o ExitOnForwardFailure=yes -o ConnectTimeout=20 -o LogLevel=ERROR ` +
          `-i ${keyFile} -p ${sshPort} ${user}@${host} > ${logFile} 2>&1 < /dev/null & echo $! > ${pidFile}`,
          { timeout: 5000 },
        );
        let open = false;
        for (let i = 0; i < 25; i++) {
          await sleep(1000);
          const probe = await sandbox.exec(
            `python3 -c "import socket,sys;s=socket.socket();s.settimeout(1);sys.exit(0 if s.connect_ex(('127.0.0.1',${port}))==0 else 1)" && echo OPEN || ` +
            `( kill -0 $(cat ${pidFile} 2>/dev/null) 2>/dev/null && echo WAIT || echo DEAD )`,
            { timeout: 4000 },
          );
          if (probe.stdout.includes('OPEN')) { open = true; break; }
          if (probe.stdout.includes('DEAD')) break;
        }
        await sandbox.exec(`rm -f ${keyFile} ${keyFile}-cert.pub`, { timeout: 3000 });   // ssh holds the key in memory; nothing on disk
        if (!open) {
          const log = await sandbox.exec(`tail -c 600 ${logFile} 2>/dev/null; kill $(cat ${pidFile} 2>/dev/null) 2>/dev/null; rm -f ${pidFile}; true`, { timeout: 4000 });
          return json({ open: false, error: 'tunnel did not open', log: (log.stdout || '').slice(0, 600) }, 502);
        }
        return json({ open: true, localPort: port, server: `socks5://127.0.0.1:${port}`, hostId: body.hostId ?? null });
      }

      if (path === '/api/proxy/close' && request.method === 'POST') {
        const body = await request.json<{ localPort?: number }>().catch(() => ({} as { localPort?: number }));
        const port = body.localPort ? Math.floor(Number(body.localPort)) : 0;
        const target = port ? `${PROXY_DIR}/${port}.pid` : `${PROXY_DIR}/*.pid`;
        const r = await sandbox.exec(`n=0; for f in ${target}; do [ -f "$f" ] || continue; kill $(cat "$f") 2>/dev/null && n=$((n+1)); rm -f "$f"; done; rm -f ${PROXY_DIR}/*.key; echo closed=$n`, { timeout: 5000 });
        return json({ closed: true, tunnels: Number((r.stdout.match(/closed=(\d+)/) || [])[1] || 0) });
      }

      if (path === '/api/proxy/status') {
        const r = await sandbox.exec(
          `for f in ${PROXY_DIR}/*.pid; do [ -f "$f" ] || continue; p=$(basename "$f" .pid); if kill -0 $(cat "$f") 2>/dev/null; then ` +
          `python3 -c "import socket,sys;s=socket.socket();s.settimeout(1);sys.exit(0 if s.connect_ex(('127.0.0.1',$p))==0 else 1)" && echo "$p open" || echo "$p dead-port"; else echo "$p dead"; fi; done; true`,
          { timeout: 6000 },
        );
        const tunnels = (r.stdout || '').trim().split('\n').filter(Boolean).map(l => { const [p, st] = l.split(' '); return { localPort: Number(p), state: st }; });
        return json({ tunnels });
      }

      // ─── Launch / relaunch the browser context (optionally through a proxy) ───
      if (path === '/api/launch' && request.method === 'POST') {
        const body = await request.json<{ proxy?: { server: string; username?: string; password?: string } | null; incognito?: boolean }>().catch(() => ({} as any));
        await ensureRelay(sandbox);
        const payload: Record<string, unknown> = {};
        if ('proxy' in body) payload.proxy = body.proxy ?? null;
        if (typeof body.incognito === 'boolean') payload.incognito = body.incognito;   // fresh throwaway Chrome profile (2026-10-25)
        const result = await relayCall(sandbox, '/launch', payload, 45000);
        if (result?.error) return json({ error: result.error }, 500);
        return json({ success: true, url: result.url, title: result.title, proxy: result.proxy ?? null, incognito: !!result.incognito });
      }

      // ─── Close ────────────────────────────────────────────────────────

      if (path === '/api/close' && request.method === 'POST') {
        await relayCall(sandbox, '/close', {});
        await sandbox.exec('pkill -f Xvfb 2>/dev/null || true');
        await sandbox.exec(`for f in ${PROXY_DIR}/*.pid; do [ -f "$f" ] && kill $(cat "$f") 2>/dev/null; done; rm -rf ${PROXY_DIR}; true`, { timeout: 5000 });
        return json({ closed: true });
      }

      // ─── Destroy DO (force fresh container on next request) ──────────
      // Call this after deploying a new container image — sandbox.destroy()
      // tears down the Durable Object so the next request spawns a new
      // instance pulling the latest image from the registry. Without this,
      // existing DOs continue running their original image indefinitely
      // (workers redeploy doesn't recycle running container instances).
      if (path === '/api/destroy' && request.method === 'POST') {
        try {
          await sandbox.destroy();
          return json({ destroyed: true });
        } catch (e) {
          return json({ destroyed: false, error: String((e as Error)?.message || e) }, 500);
        }
      }

      // ─── Root / Help ──────────────────────────────────────────────────

      return json({
        name: 'nexus-browser-sandbox',
        version: '2.0.0',
        architecture: 'Playwright relay (CDP) + xdotool (OS-level input)',
        endpoints: [
          'POST /api/setup — Start Xvfb + Playwright relay (deps pre-baked)',
          'POST /api/browse — Navigate to URL via Playwright',
          'POST /api/evaluate — Evaluate JS via Playwright',
          'POST /api/cdp — Raw CDP command via Playwright',
          'POST /api/init_script — Register a pre-load script (context.add_init_script) + apply to the current page',
          'POST /api/set_cookies — Set cookies via Playwright context',
          'POST /api/extract_cookies — Get cookies via Playwright context',
          'POST /api/detect_challenge — Check for Turnstile/challenge page',
          'POST /api/click — OS-level mouse click (human-like via xdotool)',
          'POST /api/solve_turnstile — Full orchestrated Turnstile solve',
          'POST /api/wait_for_navigation — Wait for page state change',
          'POST /api/type — Type text via xdotool',
          'POST /api/press — Press key via xdotool',
          'POST /api/keydown, /api/keyup — hold / release a key (modifiers) via xdotool',
          'POST /api/scroll — Scroll via xdotool',
          'POST /api/exec — Run shell command',
          'POST /api/interpret — Execute code in persistent session (Python/Node/Bash)',
          'POST /api/interpret/reset — Reset an interpreter session',
          'GET  /api/interpret/sessions — List active interpreter sessions',
          'GET  /api/screenshot — Get screenshot as JPEG image',
          'GET  /api/screenshot/json — Get screenshot as base64 JSON',
          'GET  /api/status — Service status (Xvfb + relay)',
          'POST /api/close — Close browser + stop services',
        ],
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      console.error(`Error on ${request.method} ${path}: ${message}`);
      return json({ error: message }, 500);
    }
  },
} satisfies ExportedHandler<Env>;

// ─── Helpers ──────────────────────────────────────────────────────────────

function sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

/**
 * Human-like mouse movement via xdotool (OS-level, undetectable).
 * Bezier-like incremental movement with jitter that decreases as cursor
 * approaches the target.
 */
/** Page→screen offset of the headed window (chrome height + centred side border + window position). */
async function windowOffset(sandbox: SandboxLike): Promise<{ ox: number; oy: number; sx: number; sy: number }> {
  try {
    const r = await relayCall(sandbox, '/window_offset', {}, 8000);
    const o = r?.offset || {};
    return { ox: Number(o.ox) || 0, oy: Number(o.oy) || 0, sx: Number(o.sx) || 0, sy: Number(o.sy) || 0 };
  } catch { return { ox: 0, oy: 0, sx: 0, sy: 0 }; }
}

async function humanMouseMove(sandbox: SandboxLike, targetX: number, targetY: number): Promise<void> {
  // Start from a random position nearby
  const startX = targetX + Math.round((Math.random() - 0.5) * 250);
  const startY = targetY + Math.round((Math.random() - 0.5) * 200);

  await sandbox.exec(`DISPLAY=${DISPLAY} xdotool mousemove ${startX} ${startY}`);
  await sleep(100 + Math.random() * 200);

  // Bezier-like incremental movement
  const steps = 6 + Math.floor(Math.random() * 5);
  for (let i = 1; i <= steps; i++) {
    const t = i / steps;
    const jitter = (1 - t) * 18;
    const mx = Math.round(startX + (targetX - startX) * t + (Math.random() - 0.5) * jitter);
    const my = Math.round(startY + (targetY - startY) * t + (Math.random() - 0.5) * jitter);
    await sandbox.exec(`DISPLAY=${DISPLAY} xdotool mousemove ${mx} ${my}`);
    await sleep(12 + Math.random() * 22);
  }

  // Final precise position
  await sandbox.exec(`DISPLAY=${DISPLAY} xdotool mousemove ${targetX} ${targetY}`);
  await sleep(60 + Math.random() * 100);
}
