/**
 * Stand-in for `@cloudflare/puppeteer` (aliased at bundle time). The Worker calls launch / connect / sessions with its BROWSER
 * binding; here the "binding" is ignored and a local Chromium is driven through puppeteer-core — the same Puppeteer API, so the
 * Worker's page code runs unchanged. sessions() lists browsers this process launched so the Worker's reconnect path still works.
 */
import puppeteer, { type Browser, type LaunchOptions } from 'puppeteer-core';
import { findChromium } from '../locate.js';

const live = new Map<string, Browser>();
let seq = 0;
export const localLaunchOptions: { headless?: boolean; args?: string[]; executablePath?: string; viewport?: { width: number; height: number } } = {};

async function launch(_binding?: unknown, _opts?: unknown): Promise<Browser> {
  const executablePath = localLaunchOptions.executablePath || findChromium();
  if (!executablePath) throw new Error('No Chromium/Chrome found. Install one, or set NEXUS_BROWSER_CHROMIUM to its path.');
  const browser = await puppeteer.launch({
    executablePath, headless: localLaunchOptions.headless ?? true,
    args: ['--no-sandbox', '--disable-dev-shm-usage', '--use-gl=swiftshader', '--enable-unsafe-swiftshader', ...(localLaunchOptions.args ?? [])],
    defaultViewport: localLaunchOptions.viewport ?? { width: 1280, height: 800 },
  } as LaunchOptions);
  const id = `local-${process.pid}-${++seq}`;
  (browser as any).sessionId = () => id;
  live.set(id, browser);
  browser.on('disconnected', () => live.delete(id));
  return browser;
}

async function connect(_binding: unknown, sessionId: string): Promise<Browser> {
  const b = live.get(sessionId);
  if (!b || !b.connected) throw new Error(`No local browser session ${sessionId}`);
  return b;
}

async function sessions(_binding?: unknown): Promise<Array<{ sessionId: string; startTime: number; connectionId?: string }>> {
  return [...live.keys()].map((sessionId) => ({ sessionId, startTime: Date.now() }));
}

async function closeAll(): Promise<void> { await Promise.all([...live.values()].map((b) => b.close().catch(() => {}))); live.clear(); }

export { launch, connect, sessions, closeAll };
export default { launch, connect, sessions, closeAll };
