const DAILY_LIMIT_SECONDS = 600; // default only — the EDGE (index.ts) enforces the REAL
// per-key limit (keyInfo.dailyLimitSeconds). This MCP-layer cap is a redundant ceiling that
// was hardcoded at 600, silently throttling higher-quota keys. Make it overridable via env
// MCP_DAILY_LIMIT_SECONDS (set once per isolate in init()); the edge stays authoritative per key.
let mcpDailyLimitSeconds = DAILY_LIMIT_SECONDS;
let mcpDailyUsage = 0;
let mcpLastResetDate = '';

function resetDailyIfNeeded(): void {
  const today = new Date().toISOString().slice(0, 10);
  if (today !== mcpLastResetDate) {
    mcpDailyUsage = 0;
    mcpLastResetDate = today;
  }
}

function getQuota(sessionStartTime: number | null): {
  sessionSeconds: number;
  dailyUsed: number;
  dailyLimit: number;
  remaining: number;
} {
  resetDailyIfNeeded();
  const sessionSeconds = sessionStartTime
    ? Math.round((Date.now() - sessionStartTime) / 1000)
    : 0;
  const dailyUsed = Math.round(mcpDailyUsage + sessionSeconds);
  return {
    sessionSeconds,
    dailyUsed,
    dailyLimit: mcpDailyLimitSeconds,
    remaining: Math.max(0, mcpDailyLimitSeconds - dailyUsed),
  };
}

