/** Registrable site of a host (example.co.uk → example.co.uk, www.shop.example.com → example.com). */
function siteOf(host: string): string {
  const p = host.toLowerCase().split('.').filter(Boolean); if (p.length <= 2) return p.join('.');
  const sld = p[p.length - 2]; return (sld.length <= 3 && p[p.length - 1].length === 2) ? p.slice(-3).join('.') : p.slice(-2).join('.');
}
/** `http(s)://user:pass@host:port` or `socks5://…` → an external proxy rule's fields (null when empty / unparseable). */
function parseProxyUrl(v: string): { server: string; username?: string; password?: string } | null {
  if (!v) return null;
  try { const u = new URL(v); const server = `${u.protocol}//${u.host}`; return { server, ...(u.username ? { username: decodeURIComponent(u.username) } : {}), ...(u.password ? { password: decodeURIComponent(u.password) } : {}) }; }
  catch { return null; }
}
/** Does the field's value hold what was typed? Masks add separators/currency (300000 → "$300,000"), so compare letters+digits only;
 *  a value LONGER than the typed text plus formatting means prefilled text was kept. */
function fieldHoldsTyped(value: string, typed: string): boolean {
  const norm = (x: string) => x.toLowerCase().replace(/[^a-z0-9]/g, '');
  const v = norm(value), t = norm(typed);
  if (!t) return true;
  if (v === t) return true;
  if (v.endsWith(t) && v.length > t.length) return false;   // appended to old text
  return v.includes(t) || t.includes(v);                     // autocomplete / mask trimmed: not a definite failure
}
