/** steps tool: the page actions allowed inside one call (no session, sandbox, auth, proxy or code tools; no nesting). */
const STEPS_ALLOWED = ['page_state', 'list_page_shortcuts', 'browse', 'click', 'type', 'keypress', 'select', 'hover', 'scroll', 'fill_form', 'wait_for', 'dismiss_overlays', 'scan', 'grab', 'snapshot', 'get_content', 'form_fields', 'evaluate', 'extract_links', 'extract_table', 'screenshot'];
const STEPS_MAX = 12;
/** One short line for a successful step inside `steps`. */
function stepBrief(name: string, obj: any, text: string): string {
  if (!obj) return text.replace(/\s+/g, ' ').slice(0, 160);
  if (name === 'browse') return `${JSON.stringify(obj.title ?? '')} ${obj.url ?? ''}${obj._wall ? ' [WALLED]' : ''}`;
  if (name === 'click' || name === 'hover') return `ok ${JSON.stringify(String(obj.element?.text ?? obj.element?.tagName ?? '').slice(0, 60))}${obj.url ? ` @ ${obj.url}` : ''}`;
  if (name === 'type') return `ok ${obj.typed ?? ''}`;
  if (name === 'select') return `ok ${JSON.stringify(obj.selected ?? '')}`;
  if (name === 'evaluate') return String(typeof obj.result === 'string' ? obj.result : JSON.stringify(obj.result ?? '')).slice(0, 200);
  return 'ok';
}

/** Wall detector for escalateIfWalled (title + URL). */
function McpAgent_WALL(title: string, url: string): string | null {
  const t = (title || '').trim();
  if (/^(403 forbidden|forbidden|access denied|access to this page has been denied|just a moment|attention required|pardon our interruption|request unsuccessful|error 403|you have been blocked)\b/i.test(t)) return `title: ${t.slice(0, 40)}`;
  if (/google\.[a-z.]+\/sorry\//i.test(url)) return 'google anti-bot (/sorry/)';
  return null;
}

// Agent mode (2026-10-21): our own SPA renders a static wallpaper for automated visitors (modules/wallpaper/agentMode.ts) —
// the particles/matrix animations cost a remote browser most of its frame budget. Set ONLY on our hosts: on any other
// site a page-visible global would be a bot fingerprint.
const AGENT_MODE_SCRIPT = `(() => { try { if (/(^|\\.)spitfire-products\\.com$|(^|\\.)nexus-terminal\\.pages\\.dev$/.test(location.hostname)) window.__NEXUS_AGENT__ = true; } catch {} })();`;

/** Stealth prelude — runs before ANY page script (like Turnstile). Serialized by puppeteer, so it must stay self-contained. */
function stealthPrelude() {
          // Hide webdriver flag (primary bot signal)
          Object.defineProperty(navigator, 'webdriver', { get: () => false });

          // Hide automation-related properties
          // @ts-ignore
          delete navigator.__proto__.webdriver;

          // Spoof Chrome runtime (headless lacks window.chrome)
          if (!(window as any).chrome) {
            (window as any).chrome = {
              runtime: {
                onMessage: { addListener: () => {}, removeListener: () => {} },
                sendMessage: () => {},
                connect: () => ({ onMessage: { addListener: () => {} }, postMessage: () => {} }),
              },
              loadTimes: () => ({}),
              csi: () => ({}),
            };
          }

          // Spoof plugins array (headless has empty plugins)
          Object.defineProperty(navigator, 'plugins', {
            get: () => {
              const plugins = [
                { name: 'Chrome PDF Plugin', filename: 'internal-pdf-viewer', description: 'Portable Document Format' },
                { name: 'Chrome PDF Viewer', filename: 'mhjfbmdgcfjbbpaeojofohoefgiehjai', description: '' },
                { name: 'Native Client', filename: 'internal-nacl-plugin', description: '' },
              ];
              // Make it look like a PluginArray
              const arr = Object.create(PluginArray.prototype);
              plugins.forEach((p, i) => { arr[i] = p; });
              Object.defineProperty(arr, 'length', { get: () => plugins.length });
              arr.item = (i: number) => plugins[i];
              arr.namedItem = (n: string) => plugins.find(p => p.name === n) || null;
              arr.refresh = () => {};
              return arr;
            },
          });

          // Spoof languages (headless can have odd values)
          Object.defineProperty(navigator, 'languages', { get: () => ['en-US', 'en'] });
          Object.defineProperty(navigator, 'language', { get: () => 'en-US' });

          // Prevent headless detection via permissions API
          const originalQuery = window.navigator.permissions?.query?.bind(window.navigator.permissions);
          if (originalQuery) {
            (window.navigator.permissions as any).query = (params: any) => {
              if (params.name === 'notifications') {
                return Promise.resolve({ state: Notification.permission } as PermissionStatus);
              }
              return originalQuery(params);
            };
          }

          // Spoof WebGL vendor/renderer (headless often shows "Google SwiftShader")
          const getParameter = WebGLRenderingContext.prototype.getParameter;
          WebGLRenderingContext.prototype.getParameter = function (param: number) {
            if (param === 37445) return 'Intel Inc.'; // UNMASKED_VENDOR_WEBGL
            if (param === 37446) return 'Intel Iris OpenGL Engine'; // UNMASKED_RENDERER_WEBGL
            return getParameter.call(this, param);
          };
          // Also patch WebGL2
          if (typeof WebGL2RenderingContext !== 'undefined') {
            const getParameter2 = WebGL2RenderingContext.prototype.getParameter;
            WebGL2RenderingContext.prototype.getParameter = function (param: number) {
              if (param === 37445) return 'Intel Inc.';
              if (param === 37446) return 'Intel Iris OpenGL Engine';
              return getParameter2.call(this, param);
            };
          }

          // Spoof connection type (headless may not have this)
          Object.defineProperty(navigator, 'connection', {
            get: () => ({
              effectiveType: '4g',
              rtt: 50,
              downlink: 10,
              saveData: false,
            }),
          });

          // Prevent iframe-based detection of headless (Turnstile uses cross-origin iframes)
          Object.defineProperty(navigator, 'maxTouchPoints', { get: () => 0 });
          Object.defineProperty(navigator, 'hardwareConcurrency', { get: () => 8 });
          Object.defineProperty(navigator, 'deviceMemory', { get: () => 8 });

          // ── WebGL renderer/vendor spoof. CreepJS checks ALL of
          //    VENDOR (7936), RENDERER (7937), UNMASKED_VENDOR_WEBGL
          //    (37445), and UNMASKED_RENDERER_WEBGL (37446). Software
          //    SwiftShader/ANGLE strings on any of them = bot. Override
          //    all four to realistic Apple Silicon hardware values.
          //    Also intercept `getExtension('WEBGL_debug_renderer_info')`
          //    so the extension probe returns a non-null object even on
          //    contexts where real Chrome would expose it. ─────────────
          try {
            const FAKE_VENDOR = 'Apple Inc.';
            const FAKE_RENDERER = 'Apple M2';
            const FAKE_VENDOR_PUBLIC = 'WebKit';
            const FAKE_RENDERER_PUBLIC = 'WebKit WebGL';
            const patchGL = (proto: any) => {
              const orig = proto.getParameter;
              proto.getParameter = function (param: number) {
                if (param === 7936) return FAKE_VENDOR_PUBLIC;       // gl.VENDOR
                if (param === 7937) return FAKE_RENDERER_PUBLIC;     // gl.RENDERER
                if (param === 37445) return FAKE_VENDOR;             // UNMASKED_VENDOR_WEBGL
                if (param === 37446) return FAKE_RENDERER;           // UNMASKED_RENDERER_WEBGL
                return orig.apply(this, arguments as any);
              };
            };
            // @ts-ignore — DOM types not in worker tsconfig
            if (typeof WebGLRenderingContext !== 'undefined') patchGL(WebGLRenderingContext.prototype);
            // @ts-ignore
            if (typeof WebGL2RenderingContext !== 'undefined') patchGL(WebGL2RenderingContext.prototype);
          } catch {}

          // ── Notification.permission: 'default' not 'denied' ──
          // Headless Chrome reports 'denied' which CreepJS flags as
          // notificationIsDenied: true. Real users default to 'default'
          // (haven't been asked yet).
          try {
            const N = (globalThis as any).Notification;
            if (N) {
              Object.defineProperty(N, 'permission', {
                get: () => 'default',
                configurable: true,
              });
            }
          } catch {}

          // ── Audio context fingerprint noise — parity with sandbox patches ──
          try {
            // @ts-ignore
            const origGetChannelData = AudioBuffer.prototype.getChannelData;
            // @ts-ignore
            AudioBuffer.prototype.getChannelData = function () {
              const data = origGetChannelData.apply(this, arguments as any);
              if (data.length === 4096) {
                for (let i = 0; i < data.length; i++) {
                  data[i] = data[i] + (Math.random() - 0.5) * 1e-7;
                }
              }
              return data;
            };
          } catch {}

          // ── Permissions API: notifications "default" not "denied" ──────
          try {
            const origQuery = (typeof navigator !== 'undefined' && navigator.permissions && navigator.permissions.query)
              ? navigator.permissions.query.bind(navigator.permissions) : null;
            if (origQuery) {
              navigator.permissions.query = function (descriptor: any) {
                if (descriptor && descriptor.name === 'notifications') {
                  // @ts-ignore
                  return Promise.resolve({ state: Notification.permission || 'default', onchange: null });
                }
                return origQuery(descriptor);
              };
            }
          } catch {}

          // ── navigator.languages: ensure non-empty ──────────────────────
          try {
            Object.defineProperty(Navigator.prototype, 'languages', {
              get: () => ['en-US', 'en'],
            });
          } catch {}
}

