/**
 * computer_use helpers (2026-10-20) — pure functions behind the `computer_use` tool, which accepts the
 * Anthropic computer-use action vocabulary (20250124 schema) so models trained on that schema can drive
 * the browser without learning our tool names. Kept dependency-free so they are unit-testable.
 */
export const COMPUTER_USE_ACTIONS = [
  'screenshot', 'left_click', 'right_click', 'middle_click', 'double_click', 'triple_click', 'left_click_drag',
  'mouse_move', 'type', 'key', 'hold_key', 'scroll', 'wait', 'cursor_position', 'left_mouse_down', 'left_mouse_up', 'zoom',
] as const;
export type ComputerUseAction = typeof COMPUTER_USE_ACTIONS[number];

/** xdotool / X11 key names (what computer-use models emit) → puppeteer KeyInput names. */
const KEY_NAMES: Record<string, string> = {
  return: 'Enter', enter: 'Enter', kp_enter: 'Enter', tab: 'Tab', escape: 'Escape', esc: 'Escape', backspace: 'Backspace',
  delete: 'Delete', del: 'Delete', space: ' ', up: 'ArrowUp', down: 'ArrowDown', left: 'ArrowLeft', right: 'ArrowRight',
  prior: 'PageUp', page_up: 'PageUp', pageup: 'PageUp', next: 'PageDown', page_down: 'PageDown', pagedown: 'PageDown',
  home: 'Home', end: 'End', insert: 'Insert', f1: 'F1', f2: 'F2', f3: 'F3', f4: 'F4', f5: 'F5', f6: 'F6', f7: 'F7', f8: 'F8',
  f9: 'F9', f10: 'F10', f11: 'F11', f12: 'F12', minus: '-', plus: '+', equal: '=', comma: ',', period: '.', slash: '/',
  backslash: '\\', semicolon: ';', apostrophe: "'", grave: '`', bracketleft: '[', bracketright: ']',
};
const MODIFIERS: Record<string, string> = {
  ctrl: 'Control', control: 'Control', alt: 'Alt', option: 'Alt', shift: 'Shift', meta: 'Meta', super: 'Meta', cmd: 'Meta',
  command: 'Meta', win: 'Meta',
};

/** "ctrl+shift+t" / "Return" / "Page_Down" / "a" → { modifiers: ['Control','Shift'], key: 'T' }. */
export function parseKeyCombo(combo: string): { modifiers: string[]; key: string } {
  const parts = combo.trim().split('+').map((p) => p.trim()).filter(Boolean);
  const modifiers: string[] = [];
  let key = '';
  for (const p of parts) {
    const low = p.toLowerCase();
    if (MODIFIERS[low]) { if (!modifiers.includes(MODIFIERS[low])) modifiers.push(MODIFIERS[low]); continue; }
    key = KEY_NAMES[low] ?? (p.length === 1 ? p : p);
  }
  if (!key && parts.length) key = parts[parts.length - 1];
  // puppeteer wants a single character as typed, or a named key; shift+letter → upper case letter
  if (key.length === 1 && modifiers.includes('Shift') && /[a-z]/.test(key)) key = key.toUpperCase();
  return { modifiers, key };
}

/** Wheel deltas for a scroll action: amount is in "clicks" (Anthropic semantics), ~100 px each. */
export function scrollDeltas(direction: 'up' | 'down' | 'left' | 'right', amount = 3, pxPerClick = 100): { deltaX: number; deltaY: number } {
  const px = Math.max(1, Math.round(amount)) * pxPerClick;
  switch (direction) {
    case 'up': return { deltaX: 0, deltaY: -px };
    case 'down': return { deltaX: 0, deltaY: px };
    case 'left': return { deltaX: -px, deltaY: 0 };
    case 'right': return { deltaX: px, deltaY: 0 };
  }
}

/** Clamp a coordinate pair to the viewport (models occasionally emit off-screen points). */
export function clampCoordinate(c: [number, number] | undefined, vw: number, vh: number): [number, number] | null {
  if (!c || c.length !== 2 || !Number.isFinite(c[0]) || !Number.isFinite(c[1])) return null;
  return [Math.min(Math.max(0, Math.round(c[0])), Math.max(0, vw - 1)), Math.min(Math.max(0, Math.round(c[1])), Math.max(0, vh - 1))];
}

/** Trace steps: args are recorded with long strings cut, never secrets-shaped values. */
export function redactArgs(args: Record<string, unknown>, maxStr = 200): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(args || {})) {
    if (v === undefined) continue;
    if (/pass|secret|token|cookie|auth/i.test(k)) { out[k] = '<redacted>'; continue; }
    out[k] = typeof v === 'string' && v.length > maxStr ? v.slice(0, maxStr) + `…(+${v.length - maxStr})` : v;
  }
  return out;
}
