/**
 * SandboxPage — Puppeteer Page-compatible interface backed by the
 * nexus-browser-sandbox worker (real Chrome in a Linux container).
 *
 * This enables the same NexusSense MCP tools to work transparently with either:
 *   - Cloudflare Browser Rendering (Puppeteer) — default, fast, cheap
 *   - Real Chrome in a sandbox container — for Turnstile/challenge-protected sites
 *
 * The agent using the MCP never knows which backend is active.
 * All calls proxy through the sandbox worker's REST API.
 *
 * Architecture (v2): Sandbox uses a persistent Playwright Python relay for CDP
 * communication (evaluate, screenshots, cookies, waiting) and xdotool for
 * OS-level input (undetectable mouse/keyboard).
 *
 * PARITY NOTES:
 *   - Injectable scripts run through evaluate() → /api/evaluate → Playwright relay.
 *   - bippy-lite: evaluateOnNewDocument() works via evaluate() (page already loaded).
 *   - Screenshots: CDP Page.captureScreenshot via Playwright, ImageMagick fallback.
 *   - mouse/keyboard: OS-level xdotool for anti-detection.
 */

// ─── SandboxElementHandle ──────────────────────────────────────────────────
class SandboxElementHandle {
  constructor(private sbxPage: SandboxPage, private selector: string) {}

  async boundingBox(): Promise<{ x: number; y: number; width: number; height: number } | null> {
    return this.sbxPage.evaluate(`(function() {
      var el = document.querySelector(${JSON.stringify(this.selector)});
      if (!el) return null;
      var r = el.getBoundingClientRect();
      return { x: r.x, y: r.y, width: r.width, height: r.height };
    })()`);
  }

  async click(): Promise<void> {
    const box = await this.boundingBox();
    if (box) {
      await this.sbxPage.mouse.click(
        box.x + box.width / 2,
        box.y + box.height / 2,
      );
    }
  }

  /** Screenshot a specific element by clipping to its bounding box via CDP */
  async screenshot(opts?: any): Promise<string> {
    const box = await this.boundingBox();
    if (!box) return '';
    return this.sbxPage.screenshot({
      ...opts,
      clip: { x: box.x, y: box.y, width: box.width, height: box.height, scale: 1 },
    });
  }
}

// ─── SandboxPage ───────────────────────────────────────────────────────────
/** CDP key definition for a Puppeteer key name (the subset agents use). */
function cdpKeyDef(key: string): { key: string; code: string; vk: number; text?: string; mod?: number } | null {
  const named: Record<string, [string, number, string?, number?]> = {
    Enter: ['Enter', 13, '\r'], Tab: ['Tab', 9], Escape: ['Escape', 27], Backspace: ['Backspace', 8], Delete: ['Delete', 46],
    ArrowUp: ['ArrowUp', 38], ArrowDown: ['ArrowDown', 40], ArrowLeft: ['ArrowLeft', 37], ArrowRight: ['ArrowRight', 39],
    Home: ['Home', 36], End: ['End', 35], PageUp: ['PageUp', 33], PageDown: ['PageDown', 34], ' ': ['Space', 32, ' '],
    Control: ['ControlLeft', 17, undefined, 2], Shift: ['ShiftLeft', 16, undefined, 8], Alt: ['AltLeft', 18, undefined, 1], Meta: ['MetaLeft', 91, undefined, 4],
  };
  const n = named[key];
  if (n) return { key, code: n[0], vk: n[1], ...(n[2] ? { text: n[2] } : {}), ...(n[3] ? { mod: n[3] } : {}) };
  if (/^[a-zA-Z]$/.test(key)) return { key, code: 'Key' + key.toUpperCase(), vk: key.toUpperCase().charCodeAt(0), text: key };
  if (/^[0-9]$/.test(key)) return { key, code: 'Digit' + key, vk: key.charCodeAt(0), text: key };
  return null;
}

/** Width of a base64 JPEG (SOF0–2 marker) or PNG (IHDR) image; 0 when it cannot be read. */
function imageWidth(b64: string): number {
  try {
    const head = atob(b64.slice(0, 40000)); const at = (i: number) => head.charCodeAt(i);
    if (at(0) === 0x89 && at(1) === 0x50) return (at(16) << 24 | at(17) << 16 | at(18) << 8 | at(19)) >>> 0;
    for (let i = 2; i + 9 < head.length;) {
      if (at(i) !== 0xFF) return 0;
      const mk = at(i + 1), len = at(i + 2) << 8 | at(i + 3);
      if (mk >= 0xC0 && mk <= 0xC2) return at(i + 7) << 8 | at(i + 8);
      i += 2 + len;
    }
  } catch { /* unreadable */ }
  return 0;
}

const X_KEYSYMS: Record<string, string> = {
  Control: 'Control_L', Shift: 'Shift_L', Alt: 'Alt_L', Meta: 'Super_L', Enter: 'Return', Backspace: 'BackSpace', Escape: 'Escape',
  ArrowUp: 'Up', ArrowDown: 'Down', ArrowLeft: 'Left', ArrowRight: 'Right', PageUp: 'Prior', PageDown: 'Next', Delete: 'Delete',
  Home: 'Home', End: 'End', Tab: 'Tab', ' ': 'space',
};
/** A Puppeteer key name → an X keysym xdotool accepts (single characters pass through; anything unsafe for the shell is dropped). */
function xKeysym(key: string): string {
  const k = X_KEYSYMS[key] ?? key;
  return /^[A-Za-z0-9_]+$/.test(k) ? k : 'VoidSymbol';
}

export class SandboxPage {
  private baseUrl: string;
  private authToken: string;
  private sessionId: string;
  private isSetup = false;
  private _url = '';
  private _title = '';
  private _mainFrame: SandboxFrame;

  mouse: {
    click: (x: number, y: number, opts?: any) => Promise<void>;
    move: (x: number, y: number, opts?: any) => Promise<void>;
    /** Press the left mouse button (no release). Pair with up() for
     *  press-and-hold gestures (PerimeterX challenges). */
    down: (opts?: { button?: 'left' | 'right' | 'middle' }) => Promise<void>;
    /** Release the previously-pressed mouse button. */
    up: (opts?: { button?: 'left' | 'right' | 'middle' }) => Promise<void>;
    /** Composite press-and-hold gesture executed entirely inside the
     *  container so timing is exact (no per-step worker→container HTTP
     *  overhead). Includes Bezier approach unless humanLikeApproach: false. */
    pressAndHold: (
      x: number,
      y: number,
      opts?: {
        holdMs?: number;
        jitterPx?: number;
        humanLikeApproach?: boolean;
      },
    ) => Promise<{ actualHoldMs: number; stepCount: number }>;
  };

  keyboard: {
    type: (text: string, opts?: { delay?: number }) => Promise<void>;
    press: (key: string) => Promise<void>;
    down: (key: string) => Promise<void>;
    up: (key: string) => Promise<void>;
  };

  constructor(baseUrl: string, authToken: string, sessionId?: string) {
    this.baseUrl = baseUrl.replace(/\/$/, '');
    this.authToken = authToken;
    this.sessionId = sessionId || crypto.randomUUID();
    this._mainFrame = new SandboxFrame(this);

    const self = this;
    this.mouse = {
      // PAGE coordinates through the relay's Playwright mouse (2026-10-20; xdotool is screen space and missed by the window chrome)
      async click(x, y, opts) {
        await self.api('/api/click', { x: Math.round(x), y: Math.round(y), humanLike: true, postClickWaitMs: 200, button: opts?.button || 'left', clickCount: opts?.clickCount || 1 });
      },
      async move(x, y, opts) {
        await self.api('/api/mouse', { action: 'move', x: Math.round(x), y: Math.round(y), humanLike: false, steps: opts?.steps || 1 });
      },
      async down(opts) {
        await self.api('/api/mouse', { action: 'down', button: opts?.button || 'left' });
      },
      async up(opts) {
        await self.api('/api/mouse', { action: 'up', button: opts?.button || 'left' });
      },
      async pressAndHold(x, y, opts) {
        // Single round-trip; the relay does the entire gesture inside the
        // container, including the per-step jitter loop. See sandbox
        // /api/press_and_hold endpoint for the bash implementation.
        const resp = await self.api('/api/press_and_hold', {
          x: Math.round(x),
          y: Math.round(y),
          holdMs: opts?.holdMs ?? 3500,
          jitterPx: opts?.jitterPx ?? 2,
          humanLikeApproach: opts?.humanLikeApproach !== false,
        });
        return {
          actualHoldMs: resp?.actualHoldMs ?? 0,
          stepCount: resp?.stepCount ?? 0,
        };
      },
    };
    this.keyboard = {
      async type(text, opts) {
        await self.api('/api/type', { text, delayMs: opts?.delay ?? 80 });
      },
      async press(key) {
        if (await self.cdpKey('down', key) && await self.cdpKey('up', key)) return;   // trusted renderer key events (see cdpKey)
        const keyMap: Record<string, string> = {
          Enter: 'Return', Tab: 'Tab', Escape: 'Escape', Backspace: 'BackSpace',
          ArrowUp: 'Up', ArrowDown: 'Down', ArrowLeft: 'Left', ArrowRight: 'Right',
          Delete: 'Delete', Home: 'Home', End: 'End', PageUp: 'Prior', PageDown: 'Next',
        };
        const k = keyMap[key] || X_KEYSYMS[key] || key;
        // a single punctuation / space character is TYPED (xdotool key names for them differ; /api/press accepts keysyms only)
        if (!/^[A-Za-z0-9_+]{1,40}$/.test(k) && key.length === 1) { await self.api('/api/type', { text: key, delayMs: 0 }); return; }
        await self.api('/api/press', { key: k });
      },
      // Puppeteer key names → X keysyms (2026-11-02: `xdotool keydown Control` is not a keysym, so every Ctrl/Shift/Alt combination —
      // ctrl+a select-all before a clear, shortcuts — silently did nothing on the sandbox).
      async down(key) {
        if (await self.cdpKey('down', key)) return;
        const r = await self.api('/api/keydown', { key: xKeysym(key) }).catch(() => null);
        if (!r?.success) await self.api('/api/exec', { command: `xdotool keydown ${xKeysym(key)}` });   // an older sandbox without the endpoint
      },
      async up(key) {
        if (await self.cdpKey('up', key)) return;
        const r = await self.api('/api/keyup', { key: xKeysym(key) }).catch(() => null);
        if (!r?.success) await self.api('/api/exec', { command: `xdotool keyup ${xKeysym(key)}` });
      },
    };
  }

  // ─── REST API helper ─────────────────────────────────────────────────────
  async api(path: string, body?: unknown): Promise<any> {
    const resp = await fetch(`${this.baseUrl}${path}`, {
      method: body !== undefined ? 'POST' : 'GET',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${this.authToken}`,
        'X-Sandbox-Session': this.sessionId,
      },
      ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
    });
    const ct = resp.headers.get('content-type') || '';
    if (!ct.includes('application/json')) {
      const text = await resp.text();
      throw new Error(`Sandbox returned non-JSON (${resp.status}): ${text.slice(0, 200)}`);
    }
    const j: any = await resp.json();
    // Keep the cached URL current from any relay reply that reports it (navigate/status/…), so url() is not stuck on the page
    // before a click-driven navigation (2026-10-25: results still said spitfire-products.com while on the AuthKit sign-in page).
    if (j && typeof j.url === 'string' && /^https?:/.test(j.url) && path !== '/api/frames') this._url = j.url;
    return j;
  }

  // ─── Setup (install Chrome + Xvfb) ────────────────────────────────────
  async setup(): Promise<void> {
    if (this.isSetup) return;
    await this.api('/api/setup', {});
    this.isSetup = true;
  }

  // ─── Residential egress pool (2026-10-20) ──────────────────────────────
  /** Open an `ssh -N -D` SOCKS tunnel in the container to a pool host. Resolves {open, server, localPort} or {open:false, error, log}. */
  async openProxy(args: { sshHost: string; sshPort: number; user?: string; key: string; cert?: string; localPort?: number; hostId?: string }): Promise<any> {
    await this.setup();
    return this.api('/api/proxy/open', args);
  }
  /** (Re)launch the Chrome context through `proxy` (null = direct). A proxy CHANGE relaunches the context (cookies/pages reset). */
  async launchWithProxy(proxy: { server: string; username?: string; password?: string } | null, incognito?: boolean): Promise<any> {
    await this.setup();
    return this.api('/api/launch', typeof incognito === 'boolean' ? { proxy, incognito } : { proxy });
  }
  async closeProxy(localPort?: number): Promise<any> {
    return this.api('/api/proxy/close', localPort ? { localPort } : {});
  }
  async proxyStatus(): Promise<any> {
    return this.api('/api/proxy/status');
  }

  // ─── Navigate ────────────────────────────────────────────────────────────
  async goto(url: string, opts?: { waitUntil?: string; timeout?: number }): Promise<void> {
    await this.setup();
    await this.api('/api/browse', { url, waitUntil: opts?.waitUntil ?? 'domcontentloaded', timeout: opts?.timeout ?? 30000 });
    this._url = url;
    try {
      this._title = (await this.evaluate('document.title')) || '';
    } catch {
      this._title = '';
    }
  }

  // ─── Solve Turnstile ────────────────────────────────────────────────────
  async solveTurnstile(url: string): Promise<any> {
    await this.setup();

    // Verify Xvfb and Playwright relay are running before Turnstile solve
    for (let i = 0; i < 3; i++) {
      const status = await this.api('/api/status');
      if (status?.xvfb === 'running' && status?.relay?.status === 'ok') break;
      await new Promise(r => setTimeout(r, 2000));
    }

    const result = await this.api('/api/solve_turnstile', { url, waitBeforeClickMs: 6000, waitAfterClickMs: 10000 });

    // Verify CDP is responsive after solve (Chrome may need extra time)
    try {
      await this.evaluate('1+1');
    } catch {
      await new Promise(r => setTimeout(r, 5000));
      try { await this.evaluate('1+1'); } catch { /* best effort */ }
    }

    // ── Post-solve verification loop ──
    // The sandbox /api/solve_turnstile endpoint doesn't verify success reliably.
    // Poll document.title to confirm we've left the challenge page.
    // "Just a moment..." title = still on challenge. Anything else = solved.
    let challengePassed = result?.challengePassed ?? false;
    const maxVerifyAttempts = 12; // 12 × 2s = 24s max wait
    for (let v = 0; v < maxVerifyAttempts; v++) {
      try {
        const title = await this.evaluate('document.title');
        const isChallengePage = typeof title === 'string' && (
          title.includes('Just a moment') ||
          title.includes('Attention Required') ||
          title.includes('Security Check') ||
          title === '' // blank title during challenge transition
        );
        if (!isChallengePage && title) {
          challengePassed = true;
          this._title = title;
          break;
        }
      } catch { /* CDP may be transitioning */ }

      // If we've waited 10s+ and still on challenge, try a retry click
      if (v === 5 && !challengePassed) {
        try {
          await this.api('/api/solve_turnstile', { url, waitBeforeClickMs: 3000, waitAfterClickMs: 5000 });
          // Give it a moment after retry
          await new Promise(r => setTimeout(r, 3000));
          try { await this.evaluate('1+1'); } catch { /* CDP warming */ }
        } catch { /* best effort retry */ }
      }

      await new Promise(r => setTimeout(r, 2000));
    }

    // Update URL from the actual browser state
    try {
      this._url = (await this.evaluate('window.location.href')) || url;
    } catch {
      this._url = url;
    }

    return { ...result, challengePassed };
  }

  // ─── Evaluate JS in the sandbox Chrome via CDP ──────────────────────────
  async evaluate(scriptOrFn: string | ((...args: any[]) => any), ...args: any[]): Promise<any> {
    let script: string;
    if (typeof scriptOrFn === 'function') {
      const argsStr = args.map(a => JSON.stringify(a)).join(', ');
      script = `(${scriptOrFn.toString()})(${argsStr})`;
    } else {
      script = scriptOrFn;
    }
    return this._evaluateRaw(script, true);
  }

  // Main-world evaluate (2026-10-19). Patchright's default world is ISOLATED: it cannot see page globals
  // (window.__REACT_DEVTOOLS_GLOBAL_HOOK__, window.__nexusBippyLite as pre-loaded by /init_script) nor the
  // __reactFiber$ expandos React sets on DOM nodes. React introspection must run here; everything else stays
  // isolated for stealth. Puppeteer has one world, so the worker only routes through this on the sandbox.
  async evaluateMain(script: string): Promise<any> {
    return this._evaluateRaw(script, false);
  }

  private async _evaluateRaw(script: string, isolatedContext: boolean): Promise<any> {

    // Retry on relay/CDP unavailable (Playwright relay may still be starting)
    const maxRetries = 5;
    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      const result = await this.api('/api/evaluate', { script, timeout: 30000, ...(isolatedContext ? {} : { isolatedContext: false }) });

      if (result.error) {
        const isCdpUnavailable = result.error.includes('ECONNREFUSED') ||
                                  result.error.includes('CDP unavailable') ||
                                  result.error.includes('no page tab');
        if (isCdpUnavailable && attempt < maxRetries) {
          // Exponential backoff: 3s, 5s, 8s, 12s, 15s (total ~43s wait)
          await new Promise(r => setTimeout(r, Math.min(3000 + attempt * 3000, 15000)));
          continue;
        }
        throw new Error(`Sandbox evaluate error: ${result.error}`);
      }
      return result.result ?? null;
    }
    throw new Error('Sandbox evaluate: max retries exceeded');
  }

  // ─── evaluateOnNewDocument ─────────────────────────────────────────────
  // Parity with Puppeteer (2026-10-19): the relay's /api/init_script registers the
  // script with Playwright's context.add_init_script, so it runs BEFORE any page
  // script on every subsequent navigation (what the React hook shim needs). The relay
  // also evaluates it on the current page (applyNow) so the page we are on gets it too.
  // If the relay predates the endpoint, fall back to the old immediate evaluate.
  async evaluateOnNewDocument(fn: any): Promise<void> {
    const script = typeof fn === 'function' ? `(${fn.toString()})()` : String(fn);
    try {
      const r = await this.api('/api/init_script', { script, applyNow: true });
      if (r && r.success) return;
    } catch { /* relay without the endpoint, or no browser yet */ }
    try { await this.evaluate(script); } catch { /* best effort — page may not be loaded yet */ }
  }

  // ─── Page info ───────────────────────────────────────────────────────────
  url(): string { return this._url; }
  /** Re-read location.href from the live page (url() is a synchronous cache; clicks and form posts navigate without telling us). */
  async syncUrl(): Promise<string> {
    try { const u = await this.evaluate('location.href'); if (typeof u === 'string' && u) this._url = u; } catch { /* keep cached */ }
    return this._url;
  }
  async title(): Promise<string> {
    try {
      const r = await this.evaluate('[document.title, location.href]');
      if (Array.isArray(r)) { this._title = r[0] || this._title; if (typeof r[1] === 'string' && r[1]) this._url = r[1]; }
    } catch { /* use cached */ }
    return this._title;
  }

  // ─── Element selection ───────────────────────────────────────────────────
  async $(selector: string): Promise<SandboxElementHandle | null> {
    const exists = await this.evaluate(
      `!!document.querySelector(${JSON.stringify(selector)})`,
    );
    return exists ? new SandboxElementHandle(this, selector) : null;
  }

  /** A real mouse-wheel event at PAGE coordinates (CDP Input.dispatchMouseEvent) — scrolls whatever is under the pointer, inner
   *  scrollers included. 2026-11-01 A/B: computer_use scroll on the sandbox used a script that left inner panels (cars.com filters,
   *  CarMax make list) and some pages unmoved. */
  async wheel(x: number, y: number, deltaX: number, deltaY: number): Promise<void> {
    await this.api('/api/cdp', { method: 'Input.dispatchMouseEvent', params: { type: 'mouseWheel', x, y, deltaX, deltaY }, timeout: 10000 });
  }

  /** Held modifiers for CDP key events (bitmask: Alt 1, Ctrl 2, Meta 4, Shift 8). */
  private _mods = 0;
  /** One key down/up through CDP Input.dispatchKeyEvent — what Puppeteer does. 2026-11-02: X-level keys (xdotool) reach the page only
   *  after a real click has put keyboard focus in the content, so keypress PageDown / ctrl+a after a navigation did nothing. These events
   *  are trusted (isTrusted) and run the browser's default actions (select-all, scroll, submit). Returns false when CDP is unavailable. */
  async cdpKey(phase: 'down' | 'up', key: string): Promise<boolean> {
    const d = cdpKeyDef(key); if (!d) return false;
    if (d.mod) this._mods = phase === 'down' ? (this._mods | d.mod) : (this._mods & ~d.mod);
    const params: Record<string, unknown> = { type: phase === 'down' ? (d.text && !(this._mods & 7) ? 'keyDown' : 'rawKeyDown') : 'keyUp', key: d.key, code: d.code,
      windowsVirtualKeyCode: d.vk, nativeVirtualKeyCode: d.vk, modifiers: this._mods };
    if (phase === 'down' && d.text && !(this._mods & 7)) { params.text = d.text; params.unmodifiedText = d.text; }
    try { const r = await this.api('/api/cdp', { method: 'Input.dispatchKeyEvent', params, timeout: 8000 }); return !r?.error; } catch { return false; }
  }

  private _dpr: number | null = null;
  /** The page's devicePixelRatio (≈1.047 on Xvfb Chrome). A page evaluate right after a navigation can fail while Patchright recreates
   *  its isolated world — that silently fell back to 1 and the next capture came out 1340×838 (2026-11-02). Order: page evaluate (retried),
   *  then CDP Runtime.evaluate (main world), then the last good value. */
  async devicePixelRatio(): Promise<number> {
    for (let i = 0; i < 2; i++) {
      try { const r = Number(await this.evaluate('window.devicePixelRatio || 1')); if (r > 0) { this._dpr = r; return r; } } catch { /* retry */ }
      await new Promise((z) => setTimeout(z, 150));
    }
    try {
      // CDP Runtime.evaluate in the page's main world (no isolated world to wait for). Page.getLayoutMetrics is NOT usable: both of its
      // viewport widths are CSS pixels in current Chrome, so its ratio reads 1.
      const m = await this.api('/api/cdp', { method: 'Runtime.evaluate', params: { expression: 'window.devicePixelRatio', returnByValue: true }, timeout: 8000 });
      const v = Number(m?.result?.value ?? m?.value);
      if (v > 0) { this._dpr = v; return v; }
    } catch { /* fall through */ }
    return this._dpr ?? 1;
  }

  // ─── Screenshot ──────────────────────────────────────────────────────────
  // Uses CDP Page.captureScreenshot for format/quality/clip parity with Puppeteer.
  // Falls back to ImageMagick (/api/screenshot/json) if CDP fails.
  async screenshot(opts?: any): Promise<string> {
    try {
      // Build CDP captureScreenshot params
      const cdpParams: Record<string, unknown> = {};
      if (opts?.type === 'png') {
        cdpParams.format = 'png';
      } else {
        cdpParams.format = 'jpeg';
        cdpParams.quality = opts?.quality ?? 80;
      }
      // The real Chrome on Xvfb runs at devicePixelRatio ≈ 1.045; CDP renders a clip at clip.scale × DPR, so every caller's scale
      // (region diffs "1:1", zoom 1–4×, 0.25 thumbnails) came out ~4.5% too large (A/B 2026-11-01). Divide by DPR → CSS-pixel scale.
      const dpr = await this.devicePixelRatio();
      if (opts?.clip) {
        cdpParams.clip = {
          x: opts.clip.x,
          y: opts.clip.y,
          width: opts.clip.width,
          height: opts.clip.height,
          scale: (opts.clip.scale ?? 1) / dpr,
        };
      }
      if (opts?.captureBeyondViewport || opts?.fullPage) {
        cdpParams.captureBeyondViewport = true;
      } else if (!opts?.clip) {
        // Viewport capture at CSS-pixel scale (A/B 2026-11-01): the real Chrome on Xvfb runs at devicePixelRatio ≈ 1.045, so an unclipped
        // capture came back 1338×838 for a 1280×800 viewport and every coordinate an agent read off it landed ~4.5% off. Clipping to the
        // viewport with scale = 1/DPR returns exactly innerWidth × innerHeight — 1:1 with click coordinates, like the default backend.
        try {
          let v: any = await this.evaluate('({w: window.innerWidth, h: window.innerHeight})');
          if (typeof v === 'string') { try { v = JSON.parse(v); } catch { v = null; } }
          if (!v?.w) { const w = Number(await this.evaluate('window.innerWidth')), h = Number(await this.evaluate('window.innerHeight')); if (w && h) v = { w, h }; }
          if (v?.w && v?.h) cdpParams.clip = { x: 0, y: 0, width: v.w, height: v.h, scale: 1 / dpr };
        } catch { /* unclipped as before */ }
      }

      const result = await this.api('/api/cdp', {
        method: 'Page.captureScreenshot',
        params: cdpParams,
        timeout: 15000,
      });

      if (result?.data) {
        // Self-check (2026-11-02): the reported devicePixelRatio can lag the real one right after a navigation (≈1.0 vs 1.047), and a
        // clipped capture then comes out ~4.7% too large (1340×838 for 1280×800). Compare the image to the size asked for; if it is off,
        // recapture once with the corrected scale and remember the real ratio.
        const clip = cdpParams.clip as { width: number; scale: number } | undefined;
        if (clip && opts?.clip) {
          const want = Math.round(opts.clip.width * (opts.clip.scale ?? 1)); const got = imageWidth(result.data);
          if (got && want && Math.abs(got - want) > 2) {
            const factor = want / got;
            clip.scale = clip.scale * factor; this._dpr = (this._dpr ?? dpr) / factor;
            const again = await this.api('/api/cdp', { method: 'Page.captureScreenshot', params: cdpParams, timeout: 15000 });
            if (again?.data) return again.data;
          }
        }
        return result.data;
      }
    } catch { /* fall through to ImageMagick */ }

    // Fallback: ImageMagick screenshot
    const result = await this.api('/api/screenshot/json');
    return result.screenshot || '';
  }

  // ─── Cookies ─────────────────────────────────────────────────────────────
  async cookies(): Promise<any[]> {
    const result = await this.api('/api/extract_cookies', {});
    return result.cookies || [];
  }

  async setCookie(...cookies: any[]): Promise<void> {
    await this.api('/api/set_cookies', { cookies });
  }

  // ─── Frames ──────────────────────────────────────────────────────────────
  private _frames: SandboxFrame[] | null = null;
  /** Synchronous view (puppeteer-shaped): the main frame plus any child frames fetched by refreshFrames(). */
  frames(): SandboxFrame[] {
    return this._frames && this._frames.length ? this._frames : [this._mainFrame];
  }
  /** Fetch the live frame list from the relay (2026-10-20). Index 0 = main; children evaluate through `frame`. */
  async refreshFrames(): Promise<SandboxFrame[]> {
    try {
      const r = await this.api('/api/frames');
      const list: Array<{ index: number; url: string; name: string }> = r?.frames || [];
      this._frames = list.map(f => f.index === 0 ? this._mainFrame : new SandboxFrame(this, f.index, f.url, f.name));
    } catch { this._frames = null; }
    return this.frames();
  }

  mainFrame(): SandboxFrame {
    return this._mainFrame;
  }

  // ─── Wait methods (polling-based) ────────────────────────────────────────
  async waitForSelector(selector: string, opts?: { timeout?: number }): Promise<void> {
    const timeout = opts?.timeout ?? 10000;
    const start = Date.now();
    while (Date.now() - start < timeout) {
      const found = await this.evaluate(
        `!!document.querySelector(${JSON.stringify(selector)})`,
      );
      if (found) return;
      await new Promise(r => setTimeout(r, 500));
    }
    throw new Error(`waitForSelector timed out: ${selector}`);
  }

  async waitForFunction(fn: string, opts?: { timeout?: number }): Promise<void> {
    const timeout = opts?.timeout ?? 10000;
    const start = Date.now();
    while (Date.now() - start < timeout) {
      const result = await this.evaluate(fn);
      if (result) return;
      await new Promise(r => setTimeout(r, 500));
    }
    throw new Error(`waitForFunction timed out`);
  }

  async waitForNavigation(opts?: { waitUntil?: string; timeout?: number }): Promise<void> {
    const timeout = opts?.timeout ?? 10000;
    const urlBefore = this._url;
    const start = Date.now();
    while (Date.now() - start < timeout) {
      await new Promise(r => setTimeout(r, 500));
      try {
        const newUrl = await this.evaluate('window.location.href');
        if (newUrl && newUrl !== urlBefore) {
          this._url = newUrl;
          return;
        }
      } catch { /* keep polling */ }
    }
    throw new Error('waitForNavigation timed out');
  }

  async waitForNetworkIdle(opts?: { idleTime?: number; timeout?: number }): Promise<void> {
    const wait = opts?.idleTime ?? 500;
    await new Promise(r => setTimeout(r, wait));
  }

  // ─── Viewport (no-op — real browser manages its own viewport) ────────────
  async setViewport(_opts: any): Promise<void> { /* no-op */ }
  async setUserAgent(_ua: string): Promise<void> { /* no-op */ }

  // ─── Content ─────────────────────────────────────────────────────────────
  async content(): Promise<string> {
    return (await this.evaluate('document.documentElement.outerHTML')) || '';
  }

  // ─── New page (returns self — sandbox has one page) ──────────────────────
  async newPage(): Promise<SandboxPage> { return this; }

  // ─── Execute shell command in sandbox container ────────────────────────
  async exec(command: string, timeout?: number): Promise<{
    stdout: string; stderr: string; exitCode: number; success: boolean;
  }> {
    return this.api('/api/exec', { command, timeout: timeout ?? 30000 });
  }

  // ─── Execute code in persistent interpreter session ────────────────────
  async interpret(code: string, language = 'python', sessionId = 'default', timeout = 30): Promise<{
    output: string; error: string | null; returnValue: string | null;
    sessionId: string; execCount: number;
  }> {
    return this.api('/api/interpret', { code, language, sessionId, timeout });
  }

  // ─── Reset an interpreter session ──────────────────────────────────────
  async resetInterpreter(language = 'python', sessionId = 'default'): Promise<any> {
    return this.api('/api/interpret/reset', { language, sessionId });
  }

  // ─── List active interpreter sessions ──────────────────────────────────
  async interpreterSessions(): Promise<any> {
    return this.api('/api/interpret/sessions');
  }

  // ─── Close ───────────────────────────────────────────────────────────────
  async close(): Promise<void> {
    await this.api('/api/close');
    this.isSetup = false;
  }
}

// ─── SandboxFrame — minimal frame interface wrapping the page ──────────────
class SandboxFrame {
  constructor(private sbxPage: SandboxPage, private index = 0, private _url = '', private _name = '') {}

  async evaluate(script: string): Promise<any> {
    if (this.index === 0) return this.sbxPage.evaluate(script);
    const r = await (this.sbxPage as any).api('/api/evaluate', { script, frame: this.index });
    if (r?.error) throw new Error(r.error);
    return r?.result ?? null;
  }

  async $(selector: string): Promise<SandboxElementHandle | null> {
    return this.index === 0 ? this.sbxPage.$(selector) : null;
  }

  url(): string { return this.index === 0 ? this.sbxPage.url() : this._url; }
  name(): string { return this._name; }
  frameIndex(): number { return this.index; }
}
