/**
 * Live view links (2026-10-22). A session's owner calls the `live_view` MCP tool and gets a short-lived signed WebSocket
 * URL for THAT session's sandbox display; `/live` verifies the signature + expiry and forwards to the sandbox Worker
 * (which proxies into the container's VNC). The signing key (AUTH_TOKEN) never leaves the Worker; only someone who can
 * call tools in the session can mint a link for it.
 */

const enc = new TextEncoder();

async function hmacHex(secret: string, msg: string): Promise<string> {
  const key = await crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const sig = await crypto.subtle.sign('HMAC', key, enc.encode(msg));
  return [...new Uint8Array(sig)].map(b => b.toString(16).padStart(2, '0')).join('');
}

/** Sign a live-view link for a sandbox session id. */
export async function signLive(secret: string, sessionId: string, expiresAt: number): Promise<string> {
  return hmacHex(secret, `live:${sessionId}:${expiresAt}`);
}

/** Constant-time check of a live-view link. */
export async function verifyLive(secret: string, sessionId: string, expiresAt: number, sig: string): Promise<boolean> {
  if (!sessionId || !sig || !Number.isFinite(expiresAt) || expiresAt < Date.now()) return false;
  const expected = await hmacHex(secret, `live:${sessionId}:${expiresAt}`);
  if (expected.length !== sig.length) return false;
  let diff = 0;
  for (let i = 0; i < expected.length; i++) diff |= expected.charCodeAt(i) ^ sig.charCodeAt(i);
  return diff === 0;
}

/** Forward a verified /live WebSocket upgrade to the sandbox Worker for that session. */
export async function forwardLive(request: Request, sandboxUrl: string, authToken: string, sessionId: string): Promise<Response> {
  const headers = new Headers();
  headers.set('Upgrade', 'websocket');
  headers.set('Authorization', `Bearer ${authToken}`);
  headers.set('X-Sandbox-Session', sessionId);
  for (const h of ['Sec-WebSocket-Protocol', 'Sec-WebSocket-Key', 'Sec-WebSocket-Version', 'Sec-WebSocket-Extensions']) {
    const v = request.headers.get(h);
    if (v) headers.set(h, v);
  }
  return fetch(`${sandboxUrl.replace(/\/$/, '')}/live`, { method: 'GET', headers });
}
