/**
 * The hosted nexus-browser MCP and its browser-sandbox, running on the user's machine — both from their own Worker source, bundled
 * unchanged (nexus-terminal/workers/nexus-browser/src/mcp.ts and workers/nexus-browser-sandbox/src/index.ts). Only the Cloudflare
 * imports are swapped for local shims:
 *   @cloudflare/puppeteer → shims/cf-puppeteer (puppeteer-core + a local Chromium)       — the default "puppeteer" backend
 *   agents/mcp McpAgent    → shims/agents-mcp
 *   ctx.storage.sql        → node:sqlite file;  env.API_KEYS (KV) → JSON file
 *   @cloudflare/sandbox    → shims/cf-sandbox (sandbox.exec runs locally)               — the "sandbox" backend
 * The sandbox Worker is served on 127.0.0.1 (sandbox-server.ts) and the MCP's own SandboxPage talks to it as it does hosted: real
 * headful Chrome on Xvfb via the Playwright relay, OS-level input via xdotool, run_code / run_command (opt-in), live view.
 * Every tool, schema and behaviour comes from the Worker source; rebuild after a Worker change (scripts/sync-browser-library.sh).
 */
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { NexusBrowserMCP } from '@worker/mcp';
import { sqlStorage, fileKV } from './shims/storage.js';
import { localLaunchOptions, closeAll } from './shims/cf-puppeteer.js';
import { startLocalSandbox, type LocalSandboxServer } from './sandbox-server.js';
import { findChromium } from './locate.js';
import { helperKeys, wrapSetProxyForVault, resolveSecretRefs } from './vault.js';
import { extraPath as installExtraPath } from './install.js';
import { registerDesktopTool } from '@nexus-cortex/desktop';

export interface LocalBrowserOptions {
  /** Where saved logins (SQLite) and the KV file live. Default ~/.nexus-cortex/browser */
  dataDir?: string;
  headless?: boolean;
  executablePath?: string;
  viewport?: { width: number; height: number };
  /** Start the local sandbox (real headful Chrome on Xvfb, xdotool, interpreters, live view). Default true. */
  sandbox?: boolean;
  /** Allow run_command / run_code to execute on this machine. Default: NEXUS_BROWSER_ALLOW_EXEC=1. */
  allowExec?: boolean;
  /** Extra Worker env values (e.g. GOOGLE_API_KEY for vision helpers). Never required for the core tools. */
  env?: Record<string, string | undefined>;
}

export async function createLocalBrowserMCP(opts: LocalBrowserOptions = {}) {
  // Installed tools (the private Python venv, extensions, a `chromium` link — set up by nexus-browser-doctor) live in the tools home;
  // per-run state (saved logins, workflows, KV) in the data dir. Both default to ~/.nexus-cortex/browser.
  const toolsHome = process.env.NEXUS_BROWSER_HOME ?? path.join(os.homedir(), '.nexus-cortex', 'browser');
  const dataDir = opts.dataDir ?? process.env.NEXUS_BROWSER_DATA_DIR ?? toolsHome;
  const chromium = opts.executablePath || findChromium() || undefined;
  Object.assign(localLaunchOptions, { headless: opts.headless, executablePath: chromium, viewport: opts.viewport });

  let sandbox: LocalSandboxServer | null = null;
  let xvfbMissing = false;
  if (opts.sandbox ?? process.env.NEXUS_BROWSER_SANDBOX !== '0') {
    const extraPath = installExtraPath() || undefined;   // NEXUS_BROWSER_EXTRA_PATH + the tool dirs `cortex browser install` recorded (e.g. Nix Xvfb)
    const sandboxDir = path.join(path.dirname(fileURLToPath(import.meta.url)), 'sandbox');
    // The container's helper commands (html2pdf, pdf2html) look for Chrome on PATH by name (google-chrome-stable / chromium); expose the
    // browser found above as `chromium` in a small bin dir of our own.
    const linkDir = path.join(toolsHome, 'bin');
    if (chromium) { try { fs.mkdirSync(linkDir, { recursive: true }); const l = path.join(linkDir, 'chromium'); try { fs.unlinkSync(l); } catch { /* none */ } fs.symlinkSync(chromium, l); } catch { /* best effort */ } }
    // The sandbox's headful Chrome runs on its own Xvfb (:99). Missing → the default backend still works; warn once.
    xvfbMissing = process.platform === 'linux' && !onPath('Xvfb', extraPath);   // the sandbox runs its own Xvfb :99; DISPLAY is irrelevant
    if (xvfbMissing) process.stderr.write(`[nexus-browser] Xvfb not found — the sandbox backend (real Chrome, incognito, live view) cannot start. ${XVFB_HINT}\n`);
    sandbox = await startLocalSandbox({
      dir: sandboxDir,
      dataDir,
      toolsHome,
      allowExec: opts.allowExec,
      env: {
        ...(chromium ? { PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH: chromium } : {}),
        // The container's helper commands (html2pdf, pdf2html) first, then any extra tool dirs, then the user's PATH.
        // The library's private Python venv (nexus-browser-doctor --install) comes before the system python3.
        PATH: [path.join(sandboxDir, 'bin'), fs.existsSync(path.join(toolsHome, 'venv', 'bin')) ? path.join(toolsHome, 'venv', 'bin') : '', linkDir, extraPath, process.env.PATH].filter(Boolean).join(path.delimiter),
      },
    });
  }

  const id = `local-${process.pid}`;
  const ctx = { id: { toString: () => id, name: id }, storage: { sql: sqlStorage(path.join(dataDir, 'state.sqlite')) }, waitUntil: (p: Promise<unknown>) => { p?.catch?.(() => {}); } };
  const env: Record<string, unknown> = {
    BROWSER: { local: true },                      // the shim ignores the binding
    API_KEYS: fileKV(path.join(dataDir, 'kv.json')),
    MCP_DAILY_LIMIT_SECONDS: '100000000',         // the hosted per-key quota has no meaning on the user's own machine
    ...(sandbox ? { SANDBOX_URL: sandbox.url, AUTH_TOKEN: sandbox.token, PUBLIC_HOST: new URL(sandbox.url).host, PUBLIC_SCHEME: 'ws',
         STDB_SENSE_URL: `${sandbox.url}/stdb`, STDB_TOKEN: sandbox.token } : {}),   // workflow store → local-store.ts
    // The user's own machine and proxies: external proxy rules are allowed unless NEXUS_BROWSER_PROXY=deny (the hosted default-deny
    // protects a metered shared pool that does not exist locally; no edge supplies a per-key policy here).
    PROXY_DEFAULT_ALLOWED: process.env.NEXUS_BROWSER_PROXY === 'deny' ? 'false' : 'true',
    // A walled page escalates through the user's own proxy first, when one is set (mcp.ts escalateIfWalled).
    // «secret:NAME» references are resolved from the vault (opted-in secrets only); an unresolvable one leaves escalation off.
    ...(await (async () => { const raw = process.env.NEXUS_BROWSER_PROXY_URL; if (!raw) return {}; const v = await resolveSecretRefs(raw); return v ? { ESCALATION_PROXY_URL: v } : {}; })()),
    // Helper keys (Gemma / Jev / Mercury for captcha decisions + vision): options > environment > the nexus-cortex secrets vault.
    ...(await helperKeys(opts.env ?? {})),
    ...opts.env,
  };
  const agent: any = new (NexusBrowserMCP as any)(ctx, env);
  await agent.init();
  wrapSetProxyForVault(agent.server);   // «secret:NAME» proxy credentials, opt-in per secret (src/vault.ts)
  // No X server for the sandbox's real Chrome → say what to install instead of Playwright's generic "headed browser without an XServer"
  // box (2026-11-03: on a machine without Xvfb an incognito browse failed this way, and a test read the missing page as "storage kept").
  if (sandbox && xvfbMissing) wrapBrowseForXServerHint(agent.server);
  // Whole-screen control (DESKTOP_SCOPE_PLAN.md): local-only, OFF unless NEXUS_BROWSER_DESKTOP=virtual|real.
  // 0.9.0: with NEXUS_DESKTOP set, desktop is served on its OWN server (nexus-cortex "nexus-desktop") — never register it twice.
  const desktop = process.env.NEXUS_DESKTOP ? null : registerDesktopTool(agent.server, toolsHome);
  return {
    /** The Worker's McpServer, with every tool registered — connect it to any MCP transport. */
    server: agent.server,
    agent,
    sandboxUrl: sandbox?.url ?? null,
    /** The `desktop` controller when NEXUS_BROWSER_DESKTOP is set (null otherwise). */
    desktop,
    async close() {
      try { await agent.browser?.close?.(); } catch { /* already closed */ }
      try { await agent.sandboxPage?.close?.(); } catch { /* not open */ }
      await closeAll();
      await sandbox?.close();
    },
  };
}

const XVFB_HINT = 'Run `cortex browser install` (or `nexus-browser-doctor --install`), install it with your package manager (Debian/Ubuntu: sudo apt-get install -y xvfb), or point NEXUS_BROWSER_EXTRA_PATH at the directory holding Xvfb.';

function onPath(bin: string, extra?: string): boolean {
  for (const d of [extra, process.env.PATH].filter(Boolean).join(path.delimiter).split(path.delimiter)) {
    if (!d) continue;
    try { fs.accessSync(path.join(d, bin), fs.constants.X_OK); return true; } catch { /* next */ }
  }
  return false;
}

/** Append the Xvfb hint to a browse result whose error is the no-X-server launch failure. */
function wrapBrowseForXServerHint(server: any): void {
  const tool = server?._registeredTools?.browse;
  if (!tool || typeof tool.handler !== 'function') return;
  const inner = tool.handler;
  tool.handler = async (args: any, extra: any) => {
    const r = await inner(args, extra);
    const parts = Array.isArray(r?.content) ? r.content : [];
    if (!parts.some((p: any) => typeof p?.text === 'string' && /without having a XServer running/i.test(p.text))) return r;
    return { ...r, content: [...parts, { type: 'text', text: `No X server: Xvfb is not installed or not on PATH. ${XVFB_HINT}` }] };
  };
}
