/**
 * Stand-in for `agents/mcp` (aliased at bundle time). The Worker's NexusBrowserMCP extends Cloudflare's McpAgent (a Durable Object);
 * it only uses env, ctx (id + storage.sql), state / setState / initialState and its own `server` field — provided here, so the
 * class runs in Node unchanged.
 */
export class McpAgent<Env = unknown, State = unknown> {
  static options: Record<string, unknown> = {};
  env: Env;
  ctx: any;
  initialState?: State;
  private _state: State | undefined;
  constructor(ctx: any, env: Env) { this.ctx = ctx; this.env = env; }
  get state(): State { return (this._state ?? this.initialState) as State; }
  setState(s: State): void { this._state = s; }
}
