import { DEEP_QUERY_FNS } from './deep-query.injectable';
/**
 * NexusSense Keypress Injectable
 *
 * Self-contained keyboard event implementation for injectable execution.
 * ZERO imports — runs in any browser context via page.evaluate().
 *
 * Args: { key, selector?, x?, y?, modifiers?: { ctrl?, shift?, alt?, meta? }, repeat? }
 * Returns: { success, element?: { tagName, id }, error? }
 */

export const KEYPRESS_SCRIPT = `(function(args) {${DEEP_QUERY_FNS}
  try {
    var element = null;

    // Find target element
    if (args.selector) {
      element = __nxDq(args.selector);
    } else if (typeof args.x === 'number' && typeof args.y === 'number') {
      element = document.elementFromPoint(args.x, args.y);
    }

    // Fall back to active element or body
    if (!element) {
      element = document.activeElement || document.body;
    }

    if (!element) {
      return { success: false, error: 'No target element found' };
    }

    // Key name → code mapping
    var KEY_CODES = {
      Enter: 'Enter', Escape: 'Escape', Tab: 'Tab', Backspace: 'Backspace',
      Delete: 'Delete', Space: 'Space', ArrowUp: 'ArrowUp', ArrowDown: 'ArrowDown',
      ArrowLeft: 'ArrowLeft', ArrowRight: 'ArrowRight', Home: 'Home', End: 'End',
      PageUp: 'PageUp', PageDown: 'PageDown',
      F1: 'F1', F2: 'F2', F3: 'F3', F4: 'F4', F5: 'F5', F6: 'F6',
      F7: 'F7', F8: 'F8', F9: 'F9', F10: 'F10', F11: 'F11', F12: 'F12'
    };

    var key = args.key;
    var code = KEY_CODES[key] || ('Key' + key.toUpperCase());
    var mods = args.modifiers || {};
    var repeatCount = args.repeat || 1;

    // Detect if key produces a printable character (fires keypress)
    var isPrintable = key.length === 1;

    for (var i = 0; i < repeatCount; i++) {
      var eventInit = {
        key: key,
        code: code,
        bubbles: true,
        cancelable: true,
        ctrlKey: !!mods.ctrl,
        shiftKey: !!mods.shift,
        altKey: !!mods.alt,
        metaKey: !!mods.meta,
        repeat: i > 0
      };

      element.dispatchEvent(new KeyboardEvent('keydown', eventInit));

      if (isPrintable) {
        element.dispatchEvent(new KeyboardEvent('keypress', eventInit));
      }

      element.dispatchEvent(new KeyboardEvent('keyup', eventInit));
    }

    return {
      success: true,
      element: {
        tagName: element.tagName.toLowerCase(),
        id: element.id || undefined
      },
      key: key,
      repeat: repeatCount
    };
  } catch (err) {
    return {
      success: false,
      error: err instanceof Error ? err.message : String(err)
    };
  }
})`;
