/**
 * sshcert.ts — short-lived OpenSSH user certificates for the residential proxy pool (2026-10-22, security fix).
 *
 * Before: the Worker sent its long-lived pool private key into the caller's sandbox container for every tunnel; the container is
 * user-controlled (run_command = root shell), so the key could be copied out. Now the Worker keeps only a CA key (secret
 * PROXY_SSH_CA_KEY, never sent anywhere) and, per tunnel, generates a fresh Ed25519 key pair and signs a certificate for it:
 * principal "root", valid for a short window, extensions = permit-port-forwarding ONLY (no pty, no agent/X11 forwarding). Pool boxes trust
 * the CA (`restrict,port-forwarding,cert-authority <ca.pub>` in authorized_keys). Anything copied out of a container expires within the
 * window and still only allows port forwarding.
 *
 * Formats (OpenSSH PROTOCOL.certkeys, PROTOCOL.key): ssh-ed25519-cert-v01@openssh.com certificates and unencrypted "openssh-key-v1"
 * private keys. WebCrypto Ed25519 only — no dependencies.
 */

const enc = new TextEncoder();

function u32(n: number): Uint8Array { const b = new Uint8Array(4); new DataView(b.buffer).setUint32(0, n >>> 0); return b; }
function u64(n: bigint): Uint8Array { const b = new Uint8Array(8); new DataView(b.buffer).setBigUint64(0, n); return b; }
function cat(...parts: Uint8Array[]): Uint8Array {
  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0)); let o = 0;
  for (const p of parts) { out.set(p, o); o += p.length; }
  return out;
}
/** SSH wire "string": uint32 length + bytes. */
function sshString(v: Uint8Array | string): Uint8Array { const b = typeof v === 'string' ? enc.encode(v) : v; return cat(u32(b.length), b); }
function b64(b: Uint8Array): string { let s = ''; for (const x of b) s += String.fromCharCode(x); return btoa(s); }
function unb64(s: string): Uint8Array { const bin = atob(s.trim()); const b = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) b[i] = bin.charCodeAt(i); return b; }

/** PKCS#8 DER prefix for an Ed25519 private key (RFC 8410) — followed by the 32-byte seed. */
const PKCS8_ED25519_PREFIX = new Uint8Array([0x30, 0x2e, 0x02, 0x01, 0x00, 0x30, 0x05, 0x06, 0x03, 0x2b, 0x65, 0x70, 0x04, 0x22, 0x04, 0x20]);

function ed25519PublicBlob(pub: Uint8Array): Uint8Array { return cat(sshString('ssh-ed25519'), sshString(pub)); }

/** Import the CA from its 32-byte seed (base64) — the form PROXY_SSH_CA_KEY is stored in. Also returns the CA public key. */
export async function importCaSeed(seedB64: string): Promise<{ key: CryptoKey; pub: Uint8Array }> {
  const seed = unb64(seedB64);
  if (seed.length !== 32) throw new Error('PROXY_SSH_CA_KEY must be the base64 of a 32-byte Ed25519 seed');
  const key = await crypto.subtle.importKey('pkcs8', cat(PKCS8_ED25519_PREFIX, seed), { name: 'Ed25519' }, true, ['sign']);
  // The public key: export as JWK (x = base64url public).
  const jwk = await crypto.subtle.exportKey('jwk', key) as JsonWebKey;
  const pub = unb64((jwk.x as string).replace(/-/g, '+').replace(/_/g, '/') + '='.repeat((4 - ((jwk.x as string).length % 4)) % 4));
  return { key, pub };
}

/** One-line authorized_keys / known form of the CA public key ("ssh-ed25519 AAAA… comment"). */
export function caPublicLine(caPub: Uint8Array, comment = 'nexus-proxy-ca'): string { return `ssh-ed25519 ${b64(ed25519PublicBlob(caPub))} ${comment}`; }

export interface MintedCredential {
  /** Unencrypted OpenSSH private key (PEM text) for the ephemeral key. */
  privateKey: string;
  /** "ssh-ed25519-cert-v01@openssh.com AAAA… comment" — write beside the key as <key>-cert.pub. */
  certificate: string;
  validBefore: number;
  serial: string;
}

/**
 * Generate an ephemeral Ed25519 key and a CA-signed user certificate for it.
 * validSeconds: lifetime (ssh only checks it at connect time — an open tunnel survives expiry; new connections need a new cert).
 */
export async function mintProxyCredential(ca: { key: CryptoKey; pub: Uint8Array }, opts: { principal: string; validSeconds: number; keyId: string; now?: number }): Promise<MintedCredential> {
  const pair = await crypto.subtle.generateKey({ name: 'Ed25519' }, true, ['sign', 'verify']) as CryptoKeyPair;
  const pub = new Uint8Array(await crypto.subtle.exportKey('raw', pair.publicKey) as ArrayBuffer);
  const pkcs8 = new Uint8Array(await crypto.subtle.exportKey('pkcs8', pair.privateKey) as ArrayBuffer);
  const seed = pkcs8.slice(pkcs8.length - 32);

  const now = Math.floor((opts.now ?? Date.now()) / 1000);
  const validAfter = BigInt(now - 60);                       // small back-skew for box clocks
  const validBefore = BigInt(now + opts.validSeconds);
  const nonce = crypto.getRandomValues(new Uint8Array(32));
  const serialBytes = crypto.getRandomValues(new Uint8Array(8));
  const serial = new DataView(serialBytes.buffer).getBigUint64(0);
  const principals = sshString(sshString(opts.principal));   // packed list of strings
  // extensions: name-sorted list of (name, empty data). Port forwarding ONLY.
  const extensions = sshString(cat(sshString('permit-port-forwarding'), sshString('')));
  const tbs = cat(
    sshString('ssh-ed25519-cert-v01@openssh.com'), sshString(nonce), sshString(pub), u64(serial), u32(1 /* SSH_CERT_TYPE_USER */),
    sshString(opts.keyId), principals, u64(validAfter), u64(validBefore),
    sshString(new Uint8Array(0)) /* critical options */, extensions, sshString(new Uint8Array(0)) /* reserved */,
    sshString(ed25519PublicBlob(ca.pub)),
  );
  const sig = new Uint8Array(await crypto.subtle.sign({ name: 'Ed25519' }, ca.key, tbs));
  const cert = cat(tbs, sshString(cat(sshString('ssh-ed25519'), sshString(sig))));

  // openssh-key-v1, unencrypted, one key; private section padded to a multiple of 8.
  const pubBlob = ed25519PublicBlob(pub);
  const check = crypto.getRandomValues(new Uint8Array(4));
  let priv = cat(check, check, sshString('ssh-ed25519'), sshString(pub), sshString(cat(seed, pub)), sshString(opts.keyId));
  const pad: number[] = []; for (let i = 1; (priv.length + pad.length) % 8 !== 0; i++) pad.push(i);
  priv = cat(priv, new Uint8Array(pad));
  const blob = cat(enc.encode('openssh-key-v1\0'), sshString('none'), sshString('none'), sshString(new Uint8Array(0)), u32(1), sshString(pubBlob), sshString(priv));
  const pem = '-----BEGIN OPENSSH PRIVATE KEY-----\n' + (b64(blob).match(/.{1,70}/g) || []).join('\n') + '\n-----END OPENSSH PRIVATE KEY-----\n';

  return { privateKey: pem, certificate: `ssh-ed25519-cert-v01@openssh.com ${b64(cert)} ${opts.keyId}`, validBefore: Number(validBefore), serial: serial.toString() };
}
