/**
 * framediff.ts — pixel diffing between computer_use frames (2026-10-22, operator: "diffing between screenshots to capture changes …
 * versus super heavy screenshots"). Every frame after an action used to be a full JPEG of the viewport. Now the DO keeps a small
 * luminance thumbnail of the last frame the agent SAW, and answers the next capture with the cheapest correct thing:
 *   unchanged → no image; a small changed area → only that region; a large change / navigation / every Nth frame → a full keyframe.
 *
 * No image library: Chrome renders the thumbnail itself (CDP captureScreenshot clip.scale, PNG), and the Worker decodes it with the
 * built-in DecompressionStream + PNG scanline unfiltering (8-bit grey / RGB / RGBA, non-interlaced — what Chrome emits).
 * Pure functions here; the Durable Object (mcp.ts) owns the capture and the per-session state.
 */

export interface LumaFrame { width: number; height: number; luma: Uint8Array }

const PNG_SIG = [137, 80, 78, 71, 13, 10, 26, 10];

function b64ToBytes(b64: string): Uint8Array {
  const bin = atob(b64); const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

async function inflate(data: Uint8Array): Promise<Uint8Array> {
  // PNG IDAT is a zlib stream — DecompressionStream('deflate') is the zlib-wrapped format.
  const ds = new DecompressionStream('deflate');
  const stream = new Blob([data]).stream().pipeThrough(ds);
  return new Uint8Array(await new Response(stream).arrayBuffer());
}

/** Decode a PNG (base64) to a luminance plane. Throws on formats Chrome does not emit (palette, 16-bit, interlaced). */
export async function decodePngLuma(b64: string): Promise<LumaFrame> {
  const b = b64ToBytes(b64);
  for (let i = 0; i < 8; i++) if (b[i] !== PNG_SIG[i]) throw new Error('not a PNG');
  const view = new DataView(b.buffer, b.byteOffset, b.byteLength);
  let p = 8, width = 0, height = 0, bitDepth = 0, colorType = 0, interlace = 0;
  const idat: Uint8Array[] = [];
  while (p < b.length) {
    const len = view.getUint32(p); const type = String.fromCharCode(b[p + 4], b[p + 5], b[p + 6], b[p + 7]);
    const body = b.subarray(p + 8, p + 8 + len);
    if (type === 'IHDR') { width = view.getUint32(p + 8); height = view.getUint32(p + 12); bitDepth = b[p + 16]; colorType = b[p + 17]; interlace = b[p + 20]; }
    else if (type === 'IDAT') idat.push(body);
    else if (type === 'IEND') break;
    p += 12 + len;
  }
  if (bitDepth !== 8 || interlace !== 0) throw new Error(`unsupported PNG (bitDepth ${bitDepth}, interlace ${interlace})`);
  const bpp = colorType === 6 ? 4 : colorType === 2 ? 3 : colorType === 0 ? 1 : colorType === 4 ? 2 : 0;
  if (!bpp) throw new Error(`unsupported PNG colour type ${colorType}`);
  const total = idat.reduce((n, c) => n + c.length, 0); const joined = new Uint8Array(total);
  let o = 0; for (const c of idat) { joined.set(c, o); o += c.length; }
  const raw = await inflate(joined);
  const stride = width * bpp; const cur = new Uint8Array(stride); const prev = new Uint8Array(stride);
  const luma = new Uint8Array(width * height);
  let r = 0;
  for (let y = 0; y < height; y++) {
    const ft = raw[r++];
    for (let x = 0; x < stride; x++) {
      const v = raw[r++]; const a = x >= bpp ? cur[x - bpp] : 0; const up = prev[x]; const c = x >= bpp ? prev[x - bpp] : 0;
      let pred = 0;
      if (ft === 1) pred = a; else if (ft === 2) pred = up; else if (ft === 3) pred = (a + up) >> 1;
      else if (ft === 4) { const pp = a + up - c; const pa = Math.abs(pp - a), pb = Math.abs(pp - up), pc = Math.abs(pp - c); pred = pa <= pb && pa <= pc ? a : pb <= pc ? up : c; }
      cur[x] = (v + pred) & 255;
    }
    for (let x = 0; x < width; x++) {
      const i = x * bpp;
      luma[y * width + x] = bpp >= 3 ? ((cur[i] * 77 + cur[i + 1] * 150 + cur[i + 2] * 29) >> 8) : cur[i];
    }
    prev.set(cur);
  }
  return { width, height, luma };
}

export interface FrameDiff {
  changedCells: number;
  totalCells: number;
  /** Fraction of the frame's cells that changed (0–1). */
  changedFraction: number;
  /** Bounding box of the changed cells in THUMBNAIL pixels [x1, y1, x2, y2], or null when nothing changed. */
  box: [number, number, number, number] | null;
}

/**
 * Compare two luminance frames on a cols x rows grid. A cell counts as changed when its mean absolute difference exceeds
 * `meanThreshold` OR at least `minPixels` pixels moved by more than `pixelThreshold` (catches a small caret/checkmark that barely moves
 * the mean, while ignoring compression-level noise). Frames of different size are reported as fully changed.
 */
export function diffFrames(a: LumaFrame, b: LumaFrame, opts: { cols?: number; rows?: number; meanThreshold?: number; pixelThreshold?: number; minPixels?: number } = {}): FrameDiff {
  const cols = opts.cols ?? 16, rows = opts.rows ?? 10;
  const total = cols * rows;
  if (a.width !== b.width || a.height !== b.height) return { changedCells: total, totalCells: total, changedFraction: 1, box: [0, 0, b.width, b.height] };
  const meanT = opts.meanThreshold ?? 2.5, pixT = opts.pixelThreshold ?? 40, minPx = opts.minPixels ?? 3;
  const W = b.width, H = b.height;
  let changed = 0, x1 = W, y1 = H, x2 = 0, y2 = 0;
  for (let cy = 0; cy < rows; cy++) {
    const ya = Math.floor(cy * H / rows), yb = Math.floor((cy + 1) * H / rows);
    for (let cx = 0; cx < cols; cx++) {
      const xa = Math.floor(cx * W / cols), xb = Math.floor((cx + 1) * W / cols);
      let sum = 0, big = 0, n = 0;
      for (let y = ya; y < yb; y++) {
        const row = y * W;
        for (let x = xa; x < xb; x++) { const d = Math.abs(a.luma[row + x] - b.luma[row + x]); sum += d; if (d > pixT) big++; n++; }
      }
      if (n && (sum / n > meanT || big >= minPx)) {
        changed++; if (xa < x1) x1 = xa; if (ya < y1) y1 = ya; if (xb > x2) x2 = xb; if (yb > y2) y2 = yb;
      }
    }
  }
  return { changedCells: changed, totalCells: total, changedFraction: changed / total, box: changed ? [x1, y1, x2, y2] : null };
}
