/**
 * Stand-in for `@cloudflare/sandbox` (aliased at bundle time) so the browser-sandbox Worker (nexus-terminal/workers/
 * nexus-browser-sandbox/src/index.ts) runs unchanged on the user's machine. Hosted, `sandbox.exec(cmd)` runs a shell command inside the
 * container; here it runs the same command in a local bash. The container's fixed paths are mapped to the local install directory:
 *   /opt/playwright-relay.py, /opt/code-interpreter.py, /opt/extensions → <dir>/…   (copied there by build.mjs)
 * Everything else the Worker runs (curl to the relay on 127.0.0.1:8222, Xvfb on :99, xdotool, x11vnc, websockify) uses the local tools.
 */
import { spawn } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

export const sandboxConfig: { dir: string; extensionsDir: string; env: Record<string, string>; vncPort: number; wsPort: number;
  display: number; relayPort: number; interpPort: number; cdpPort: number } =
  { dir: '', extensionsDir: '', env: {}, vncPort: 5900, wsPort: 6080, display: 99, relayPort: 8222, interpPort: 8223, cdpPort: 9222 };

/** One sandbox per PROCESS (2026-11-02): the Worker's container values (display :99, relay 8222, interpreter 8223, CDP 9222, one Chrome
 *  profile) are fixed, so a second process on the same machine — two cortex sessions, or a test run during the post-deploy sync — used to
 *  kill the first one's Xvfb/relay at startup and drive the same Chrome. Each process now claims a display number with a lock file in the
 *  temp dir (pid inside; a dead pid's lock is stale) and gets its own ports and profile. Returns the claimed display. */
export function claimSandboxInstance(): number {
  const alive = (pid: number) => { try { process.kill(pid, 0); return true; } catch (e) { return (e as NodeJS.ErrnoException).code === 'EPERM'; } };
  const ownerOf = (f: string) => { try { return Number(fs.readFileSync(f, 'utf8').trim()) || 0; } catch { return 0; } };
  for (let n = 99; n < 160; n++) {
    const lock = path.join(os.tmpdir(), `nexus-browser-sandbox-${n}.lock`);
    const xlock = `/tmp/.X${n}-lock`;   // a display some OTHER program holds (Xvfb writes its pid here)
    const xo = ownerOf(xlock);
    const o = ownerOf(lock);
    if (o && o !== process.pid && alive(o)) continue;
    if (xo && alive(xo) && !(o && o !== process.pid)) {
      // an X server on :n not started by a nexus-browser instance we can account for → leave it alone
      if (!o) continue;
    }
    try { fs.writeFileSync(lock, String(process.pid)); } catch { continue; }
    if (ownerOf(lock) !== process.pid) continue;
    sandboxConfig.display = n;
    const exitClean = () => { try { if (ownerOf(lock) === process.pid) fs.rmSync(lock); } catch { /* gone */ } };
    process.once('exit', exitClean);
    return n;
  }
  throw new Error('no free display for the local browser sandbox (:99–:159 all in use)');
}

function mapPaths(cmd: string): string {
  if (!sandboxConfig.dir) return cmd;
  return cmd.replace(/\/opt\/extensions\b/g, sandboxConfig.extensionsDir || `${sandboxConfig.dir}/extensions`)   // the user's data dir (doctor --install fills it)
    .replace(/\/opt\/(playwright-relay\.py|code-interpreter\.py)\b/g, (_m, f) => `${sandboxConfig.dir}/${f}`)
    // The container binds websockify to its network address for the platform proxy; on a user's machine that would expose an
    // unpassworded VNC of the browser to their LAN. Locally it listens on loopback only (the sandbox server proxies to it).
    .replace(/websockify 0\.0\.0\.0:/g, 'websockify 127.0.0.1:')
    // Live view's fixed container ports (x11vnc 5900, websockify 6080) are often taken on a real machine (5900 = macOS Screen Sharing,
    // desktop VNC); the local sandbox uses free ports chosen at startup.
    .replace(/\b5900\b/g, String(sandboxConfig.vncPort)).replace(/\b6080\b/g, String(sandboxConfig.wsPort))
    // This process's own display and ports (claimSandboxInstance); markers let cleanup find exactly this instance's processes.
    .replace(/(^|[^0-9]):99\b/g, `$1:${sandboxConfig.display}`)
    .replace(/127\.0\.0\.1:8222\b/g, `127.0.0.1:${sandboxConfig.relayPort}`).replace(/127\.0\.0\.1:8223\b/g, `127.0.0.1:${sandboxConfig.interpPort}`)
    .replace(/pgrep -x x11vnc\b/g, `pgrep -f "x11vnc -display :${sandboxConfig.display} "`)
    .replace(/(playwright-relay\.py|code-interpreter\.py)(\s*&)/g, `$1 --nb-display=${sandboxConfig.display}$2`)
    // The container's Chrome path is hard-coded in the relay start command; use the browser found on this machine.
    .replace(/\/usr\/bin\/google-chrome-stable\b/g, sandboxConfig.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH || '/usr/bin/google-chrome-stable');
}

export interface ExecResult { stdout: string; stderr: string; exitCode: number; success: boolean }

class LocalSandbox {
  constructor(readonly id: string) {}
  /** Output goes to temp FILES, not pipes: a command that starts a background process (Xvfb …&, the relay) leaves that process
   *  holding the output — with a pipe it would die of SIGPIPE once we stop reading; a file it can keep writing. Resolves when bash exits. */
  exec(cmd: string, opts: { timeout?: number; env?: Record<string, string> } = {}): Promise<ExecResult> {
    return new Promise((resolve) => {
      const base = path.join(os.tmpdir(), `nb-exec-${process.pid}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`);
      const out = fs.openSync(`${base}.out`, 'w'), err = fs.openSync(`${base}.err`, 'w');
      // The command goes in a script FILE, not `bash -c <cmd>`: the Worker checks for its own processes with `pgrep -f "Xvfb :99"`,
      // which would otherwise match the checking shell's own argv and report Xvfb up when it is not (in the container argv stays clean).
      fs.writeFileSync(`${base}.sh`, mapPaths(cmd), { mode: 0o600 });
      const inst = { NB_RELAY_PORT: String(sandboxConfig.relayPort), NB_INTERP_PORT: String(sandboxConfig.interpPort), NB_CDP_PORT: String(sandboxConfig.cdpPort),
        ...(sandboxConfig.display !== 99 ? { NB_PROFILE_DIR: `/tmp/chrome-profile-${sandboxConfig.display}` } : {}),
        // The relay takes its sandbox down when this process dies, however it dies (2026-11-03: a SIGKILLed browse delegate left relay +
        // Chrome + Xvfb on :99 and the next delegate's Chrome could not take the profile).
        NB_OWNER_PID: String(process.pid) };
      const child = spawn('bash', [`${base}.sh`], { env: { ...process.env, ...sandboxConfig.env, ...inst, ...(opts.env ?? {}) }, stdio: ['ignore', out, err] });
      let done = false; let extra = '';
      const finish = (code: number) => {
        if (done) return; done = true; clearTimeout(timer);
        fs.closeSync(out); fs.closeSync(err); fs.rm(`${base}.sh`, () => {});
        const read = (f: string) => { try { return fs.readFileSync(f, 'utf8'); } catch { return ''; } finally { fs.rm(f, () => {}); } };
        const stdout = read(`${base}.out`), stderr = read(`${base}.err`) + extra;
        resolve({ stdout, stderr, exitCode: code, success: code === 0 });
      };
      const timer = setTimeout(() => { child.kill('SIGKILL'); extra = `\n[local sandbox] timed out after ${opts.timeout} ms`; finish(124); }, opts.timeout ?? 120000);
      child.on('exit', (code) => finish(code ?? 1));
      child.on('error', (e) => { extra = String(e); finish(127); });
    });
  }
  async destroy(): Promise<void> {
    // Hosted, this deletes the container. Locally: stop the processes the sandbox started.
    await stopLocalSandboxProcesses();
  }
  /** Live view: the local server upgrades the WebSocket itself (see sandbox-server.ts); a fetch-level call only gets this marker. */
  async wsConnect(_req: Request, port: number): Promise<Response> {
    const local = port === 6080 ? sandboxConfig.wsPort : port;
    return new Response(null, { status: 426, headers: { 'x-local-ws-port': String(local) } });
  }
}

const sandboxes = new Map<string, LocalSandbox>();
export function getSandbox(_ns: unknown, id: string, _opts?: unknown): LocalSandbox {
  let s = sandboxes.get(id); if (!s) { s = new LocalSandbox(id); sandboxes.set(id, s); } return s;
}
export async function proxyToSandbox(_req: Request, _env: unknown): Promise<Response | null> { return null; }
export class Sandbox {}

/** Stop the processes THIS instance's sandbox starts (relay, interpreter, Xvfb, x11vnc, websockify) — at startup (leftovers of an earlier,
 *  dead owner of the same display) and on close. Matches only this instance's display, ports and markers. */
export function stopLocalSandboxProcesses(): Promise<void> {
  return new Promise((resolve) => {
    const d = sandboxConfig.display;
    const pats = [`${sandboxConfig.dir}/playwright-relay.py --nb-display=${d}`, `${sandboxConfig.dir}/code-interpreter.py --nb-display=${d}`, `Xvfb :${d} `,
      `x11vnc -display :${d} `, `websockify 127.0.0.1:${sandboxConfig.wsPort} `];
    // …and a Chrome still holding this instance's profile (its relay may already be gone): it blocks the next Chrome on that profile.
    const profile = d !== 99 ? `/tmp/chrome-profile-${d}` : '/tmp/chrome-profile';
    const pattern = [...pats.map((p) => p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')), `--user-data-dir=${profile}( |$)`].join('|');
    // SIGTERM first (the relay closes its browser cleanly), then SIGKILL whatever is left: with Xvfb gone the relay's graceful
    // browser close can hang, and a surviving relay would be reused by the next run.
    const kill = (sig: string, then: () => void) => { const k = spawn('pkill', [sig, '-f', pattern], { stdio: 'ignore' }); k.on('exit', then); k.on('error', then); };
    kill('-TERM', () => setTimeout(() => kill('-KILL', () => setTimeout(resolve, 200)), 2000));
  });
}
